@Test
public void testCountWithJoin() throws Exception {
    IgniteCache<Integer, RISK> RISK = client.getOrCreateCache(new CacheConfiguration<Integer, RISK>().setName("RISK").setSqlSchema("PUBLIC").setQueryEntities(F.asList(new QueryEntity(Integer.class, RISK.class).setTableName("RISK").setKeyFields(new HashSet<>(Arrays.asList("TRADEID", "TRADEVER"))))).setBackups(1));
    IgniteCache<Integer, TRADE> TRADE = client.getOrCreateCache(new CacheConfiguration<Integer, TRADE>().setName("TRADE").setSqlSchema("PUBLIC").setQueryEntities(F.asList(new QueryEntity(Integer.class, TRADE.class).setTableName("TRADE").setKeyFields(new HashSet<>(Arrays.asList("TRADEID", "TRADEVER"))))).setBackups(1));
    IgniteCache<Integer, BATCH> BATCH = client.getOrCreateCache(new CacheConfiguration<Integer, BATCH>().setName("BATCH").setSqlSchema("PUBLIC").setQueryEntities(F.asList(new QueryEntity(Integer.class, BATCH.class).setTableName("BATCH"))).setCacheMode(CacheMode.REPLICATED));
    int numRiskRows = 65_000;
    Map<Integer, RISK> mRisk = new HashMap<>(numRiskRows);
    for (int i = 0; i < numRiskRows; i++) mRisk.put(i, new RISK(i));
    RISK.putAll(mRisk);
    Map<Integer, TRADE> mTrade = new HashMap<>(200);
    for (int i = 0; i < 200; i++) mTrade.put(i, new TRADE(i));
    TRADE.putAll(mTrade);
    for (int i = 0; i < 80; i++) BATCH.put(i, new BATCH(i));
    awaitPartitionMapExchange(true, true, null);
    List<String> joinConverters = Arrays.asList("CorrelatedNestedLoopJoin", "MergeJoinConverter", "NestedLoopJoinConverter");
    // CorrelatedNestedLoopJoin skipped intentionally since it takes too long to finish
    // the query with only CNLJ
    for (int i = 1; i < joinConverters.size(); i++) {
        String currJoin = joinConverters.get(i);
        log.info("Verifying " + currJoin);
        String disableRuleArgs = joinConverters.stream().filter(rn -> !rn.equals(currJoin)).collect(Collectors.joining("', '", "'", "'"));
        String sql = "SELECT /*+ DISABLE_RULE(" + disableRuleArgs + ") */ count(*)" + " FROM RISK R," + " TRADE T," + " BATCH B " + "WHERE R.BATCHKEY = B.BATCHKEY " + "AND R.TRADEID = T.TRADEID " + "AND R.TRADEVER = T.TRADEVER " + "AND T.BOOK = 'BOOK' " + "AND B.LS = TRUE";
        // loop for test execution.
        for (int j = 0; j < 10; j++) {
            List<List<?>> res = sql(sql);
            assertEquals(1, res.size());
            assertEquals(1, res.get(0).size());
            assertEquals(40L, res.get(0).get(0));
            awaitReservationsRelease("RISK");
            awaitReservationsRelease("TRADE");
            awaitReservationsRelease("BATCH");
            assertFalse(lsnr.check());
        }
    }
    listeningLog.clearListeners();
}

