/**
 * Test verifies that 1) proper indexes will be chosen for queries with
 * different kinds of ordering, and 2) result set returned will be
 * sorted as expected.
 *
 * @throws IgniteInterruptedCheckedException If failed.
 */
@Test
public void testSelectWithOrdering() throws IgniteInterruptedCheckedException {
    sql("drop table if exists test_tbl", true);
    sql("create table test_tbl (c1 int)", true);
    sql("insert into test_tbl values (1), (2), (3), (null)", true);
    sql("create index idx_asc on test_tbl (c1)", true);
    sql("create index idx_desc on test_tbl (c1 desc)", true);
    assertQuery(client, "select c1 from test_tbl ORDER BY c1").matches(containsIndexScan("PUBLIC", "TEST_TBL", "IDX_ASC")).matches(not(containsSubPlan("IgniteSort"))).ordered().returns(new Object[] { null }).returns(1).returns(2).returns(3).check();
    assertQuery(client, "select c1 from test_tbl ORDER BY c1 asc nulls first").matches(containsIndexScan("PUBLIC", "TEST_TBL", "IDX_ASC")).matches(not(containsSubPlan("IgniteSort"))).ordered().returns(new Object[] { null }).returns(1).returns(2).returns(3).check();
    assertQuery(client, "select c1 from test_tbl ORDER BY c1 asc nulls last").matches(containsSubPlan("IgniteSort")).ordered().returns(1).returns(2).returns(3).returns(new Object[] { null }).check();
    assertQuery(client, "select c1 from test_tbl ORDER BY c1 desc").matches(containsIndexScan("PUBLIC", "TEST_TBL", "IDX_DESC")).matches(not(containsSubPlan("IgniteSort"))).ordered().returns(3).returns(2).returns(1).returns(new Object[] { null }).check();
    assertQuery(client, "select c1 from test_tbl ORDER BY c1 desc nulls first").matches(containsSubPlan("IgniteSort")).ordered().returns(new Object[] { null }).returns(3).returns(2).returns(1).check();
    assertQuery(client, "select c1 from test_tbl ORDER BY c1 desc nulls last").matches(containsIndexScan("PUBLIC", "TEST_TBL", "IDX_DESC")).matches(not(containsSubPlan("IgniteSort"))).ordered().returns(3).returns(2).returns(1).returns(new Object[] { null }).check();
}

