@Test
public void testIndexSpool() throws Exception {
    ExecutionContext<Object[]> ctx = executionContext(F.first(nodes()), UUID.randomUUID(), 0);
    IgniteTypeFactory tf = ctx.getTypeFactory();
    RelDataType rowType = TypeUtils.createRowType(tf, int.class, String.class, int.class);
    int inBufSize = U.field(AbstractNode.class, "IN_BUFFER_SIZE");
    int[] sizes = { 1, inBufSize / 2 - 1, inBufSize / 2, inBufSize / 2 + 1, inBufSize, inBufSize + 1, inBufSize * 4 };
    int[] eqCnts = { 1, 10 };
    for (int size : sizes) {
        for (int eqCnt : eqCnts) {
            // (filter, search, expected result size)
            GridTuple3<Predicate<Object[]>, Object[], Integer>[] testBounds;
            if (size == 1) {
                testBounds = new GridTuple3[] { new GridTuple3(null, new Object[] { 0, null, null }, eqCnt) };
            } else {
                testBounds = new GridTuple3[] { new GridTuple3(null, new Object[] { size / 2, null, null }, eqCnt), new GridTuple3(null, new Object[] { size / 2 + 1, null, null }, eqCnt), new GridTuple3((Predicate<Object[]>) r -> ((int) r[2]) == 0, new Object[] { size / 2 + 1, null, null }, 1) };
            }
            log.info("Check: size=" + size);
            ScanNode<Object[]> scan = new ScanNode<>(ctx, rowType, new TestTable(size * eqCnt, rowType, (rowId) -> rowId / eqCnt, (rowId) -> "val_" + (rowId % eqCnt), (rowId) -> rowId % eqCnt) {

                boolean first = true;

                @Override
                @NotNull
                public Iterator<Object[]> iterator() {
                    assertTrue("Rewind right", first);
                    first = false;
                    return super.iterator();
                }
            });
            Object[] searchRow = new Object[3];
            TestPredicate testFilter = new TestPredicate();
            IndexSpoolNode<Object[]> spool = IndexSpoolNode.createHashSpool(ctx, rowType, ImmutableBitSet.of(0), testFilter, () -> searchRow);
            spool.register(Arrays.asList(scan));
            RootRewindable<Object[]> root = new RootRewindable<>(ctx, rowType);
            root.register(spool);
            for (GridTuple3<Predicate<Object[]>, Object[], Integer> bound : testBounds) {
                log.info("Check: bound=" + bound);
                // Set up bounds
                testFilter.delegate = bound.get1();
                System.arraycopy(bound.get2(), 0, searchRow, 0, searchRow.length);
                assertEquals("Invalid result size", (int) bound.get3(), root.rowsCount());
            }
            root.closeRewindableRoot();
        }
    }
}

