@Test
public void testNullsInSearchRow() {
    ExecutionContext<Object[]> ctx = executionContext(F.first(nodes()), UUID.randomUUID(), 0);
    RelDataType rowType = TypeUtils.createRowType(ctx.getTypeFactory(), int.class, int.class);
    ScanNode<Object[]> scan = new ScanNode<>(ctx, rowType, new TestTable(4, rowType, (rowId) -> (rowId & 1) == 0 ? null : 1, (rowId) -> (rowId & 2) == 0 ? null : 1));
    Object[] searchRow = new Object[2];
    IndexSpoolNode<Object[]> spool = IndexSpoolNode.createHashSpool(ctx, rowType, ImmutableBitSet.of(0, 1), null, () -> searchRow);
    spool.register(scan);
    RootRewindable<Object[]> root = new RootRewindable<>(ctx, rowType);
    root.register(spool);
    List<T2<Object[], Integer>> testBounds = F.asList(new T2<>(new Object[] { null, null }, 0), new T2<>(new Object[] { 1, null }, 0), new T2<>(new Object[] { null, 1 }, 0), new T2<>(new Object[] { 1, 1 }, 1));
    for (T2<Object[], Integer> bound : testBounds) {
        System.arraycopy(bound.get1(), 0, searchRow, 0, searchRow.length);
        assertEquals("Invalid result size", (int) bound.get2(), root.rowsCount());
    }
    root.closeRewindableRoot();
}

