@Test
public void testIndexSpool() throws Exception {
    ExecutionContext<Object[]> ctx = executionContext(F.first(nodes()), UUID.randomUUID(), 0);
    IgniteTypeFactory tf = ctx.getTypeFactory();
    RelDataType rowType = TypeUtils.createRowType(tf, int.class, String.class, int.class);
    int inBufSize = U.field(AbstractNode.class, "IN_BUFFER_SIZE");
    int[] sizes = { 1, inBufSize / 2 - 1, inBufSize / 2, inBufSize / 2 + 1, inBufSize, inBufSize + 1, inBufSize * 4 };
    for (int size : sizes) {
        // (filter, lower, upper, expected result size)
        GridTuple4<Predicate<Object[]>, Object[], Object[], Integer>[] testBounds;
        if (size == 1) {
            testBounds = new GridTuple4[] { new GridTuple4(null, new Object[] { null, null, null }, new Object[] { null, null, null }, 1), new GridTuple4(null, new Object[] { 0, null, null }, new Object[] { 0, null, null }, 1) };
        } else {
            testBounds = new GridTuple4[] { new GridTuple4(null, new Object[] { null, null, null }, new Object[] { null, null, null }, size), new GridTuple4(null, new Object[] { size / 2, null, null }, new Object[] { size / 2, null, null }, 1), new GridTuple4(null, new Object[] { size / 2 + 1, null, null }, new Object[] { size / 2 + 1, null, null }, 1), new GridTuple4(null, new Object[] { size / 2, null, null }, new Object[] { null, null, null }, size - size / 2), new GridTuple4(null, new Object[] { null, null, null }, new Object[] { size / 2, null, null }, size / 2 + 1), new GridTuple4<>((Predicate<Object[]>) (r -> ((int) r[0]) < size / 2), new Object[] { null, null, null }, new Object[] { size / 2, null, null }, size / 2) };
        }
        log.info("Check: size=" + size);
        ScanNode<Object[]> scan = new ScanNode<>(ctx, rowType, new TestTable(size, rowType) {

            boolean first = true;

            @Override
            @NotNull
            public Iterator<Object[]> iterator() {
                assertTrue("Rewind right", first);
                first = false;
                return super.iterator();
            }
        });
        Object[] lower = new Object[3];
        Object[] upper = new Object[3];
        TestPredicate testFilter = new TestPredicate();
        IndexSpoolNode<Object[]> spool = IndexSpoolNode.createTreeSpool(ctx, rowType, RelCollations.of(ImmutableIntList.of(0)), (o1, o2) -> o1[0] != null ? ((Comparable) o1[0]).compareTo(o2[0]) : 0, testFilter, () -> lower, () -> upper);
        spool.register(Arrays.asList(scan));
        RootRewindable<Object[]> root = new RootRewindable<>(ctx, rowType);
        root.register(spool);
        for (GridTuple4<Predicate<Object[]>, Object[], Object[], Integer> bound : testBounds) {
            log.info("Check: bound=" + bound);
            // Set up bounds
            testFilter.delegate = bound.get1();
            System.arraycopy(bound.get2(), 0, lower, 0, lower.length);
            System.arraycopy(bound.get3(), 0, upper, 0, upper.length);
            assertEquals("Invalid result size", (int) bound.get4(), root.rowsCount());
        }
        root.closeRewindableRoot();
    }
}

