    assertQuery("select count(case when name not like 'I%' then 1 else null end) from person").returns(2L).check();
    assertQuery("select count(name) from person where salary > 10").returns(1L).check();
    assertQuery("select count(*) from person where salary > 10").returns(2L).check();
    assertQuery("select count(1) from person where salary > 10").returns(2L).check();
    assertQuery("select count(*) from person where name is not null").returns(4L).check();
    assertQuery("select count(name) filter (where salary > 10) from person").returns(1L).check();
    assertQuery("select count(*) filter (where salary > 10) from person").returns(2L).check();
    assertQuery("select count(1) filter (where salary > 10) from person").returns(2L).check();
    assertQuery("select salary, count(name) from person group by salary order by salary").returns(10d, 3L).returns(15d, 1L).check();
    assertQuery("select salary, count(*) from person group by salary order by salary").returns(10d, 3L).returns(15d, 2L).check();
    assertQuery("select salary, count(1) from person group by salary order by salary").returns(10d, 3L).returns(15d, 2L).check();
    assertQuery("select salary, count(1), sum(1) from person group by salary order by salary").returns(10d, 3L, 3L).returns(15d, 2L, 2L).check();
    assertQuery("select salary, name, count(1), sum(salary) from person group by salary, name order by salary").returns(10d, "Igor", 1L, 10d).returns(10d, "Roma", 2L, 20d).returns(15d, "Ilya", 1L, 15d).returns(15d, null, 1L, 15d).check();
    assertQuery("select salary, count(name) from person group by salary having salary < 10 order by salary").check();
    assertQuery("select count(_key), _key from person group by _key").returns(1L, 0).returns(1L, 1).returns(1L, 2).returns(1L, 3).returns(1L, 4).check();
    assertQuery("select count(name), name from person group by name").returns(1L, "Igor").returns(1L, "Ilya").returns(2L, "Roma").returns(0L, null).check();
    assertQuery("select avg(salary) from person").returns(12.0).check();
}

