        assertQuery("SELECT oth FROM t order by id").ordered().returns("str").returns(22).returns(33.5f).returns(44.5d).returns(UUID.fromString("fd10556e-fc27-4a99-b5e4-89b8344cb3ce")).returns(new Object[] { null }).returns(new Object[] { null }).check();
