/**
 * Important! Don`t change query call sequence in this test. This also tests correctness of
 * {@link org.apache.ignite.internal.processors.query.calcite.exec.exp.ExpressionFactoryImpl#SCALAR_CACHE} usage.
 */
@Test
public void testRangeWithCache() throws Exception {
    IgniteCache<Integer, Integer> cache = grid(0).getOrCreateCache(new CacheConfiguration<Integer, Integer>("test").setBackups(1).setIndexedTypes(Integer.class, Integer.class));
    for (int i = 0; i < 100; i++) cache.put(i, i);
    awaitPartitionMapExchange();
    // Correlated INNER join.
    assertQuery("SELECT t._val FROM \"test\".Integer t WHERE t._val < 5 AND " + "t._key in (SELECT x FROM table(system_range(t._val, t._val))) ").returns(0).returns(1).returns(2).returns(3).returns(4).check();
    // Correlated LEFT joins.
    assertQuery("SELECT t._val FROM \"test\".Integer t WHERE t._val < 5 AND " + "EXISTS (SELECT x FROM table(system_range(t._val, t._val)) WHERE mod(x, 2) = 0) ").returns(0).returns(2).returns(4).check();
    assertQuery("SELECT t._val FROM \"test\".Integer t WHERE t._val < 5 AND " + "NOT EXISTS (SELECT x FROM table(system_range(t._val, t._val)) WHERE mod(x, 2) = 0) ").returns(1).returns(3).check();
    assertEquals(0, sql("SELECT t._val FROM \"test\".Integer t WHERE " + "EXISTS (SELECT x FROM table(system_range(t._val, null))) ").size());
    // Non-correlated join.
    assertQuery("SELECT t._val FROM \"test\".Integer t JOIN table(system_range(1, 50)) as r ON t._key = r.x " + "WHERE mod(r.x, 10) = 0").returns(10).returns(20).returns(30).returns(40).returns(50).check();
}

