    sql = "SELECT val FROM tbl WHERE id >= 10 and id < 20 ORDER BY id DESC, val";
    checker = assertQuery(initNode, sql).matches(CoreMatchers.not(QueryChecker.containsSubPlan("IndexSpool"))).matches(CoreMatchers.not(QueryChecker.containsSubPlan("IgniteSort"))).matches(QueryChecker.containsIndexScan("PUBLIC", "TBL", "IDX_ID_VAL")).returns("val19").returns("val18").returns("val17").returns("val16").returns("val15").returns("val14").returns("val13").returns("val12").returns("val11").returns("val10").ordered();
    checkRebuildIndexQuery(grid(1), checker, checker);
    // Order by another collation.
    sql = "SELECT * FROM tbl WHERE val BETWEEN 'val10' AND 'val15' ORDER BY val";
    checker = assertQuery(initNode, sql).matches(QueryChecker.containsSubPlan("IgniteSort")).matches(QueryChecker.containsIndexScan("PUBLIC", "TBL", "IDX_VAL")).returns(10, "val10", "val10").returns(11, "val11", "val11").returns(12, "val12", "val12").returns(13, "val13", "val13").returns(14, "val14", "val14").returns(15, "val15", "val15").ordered();
    checkRebuildIndexQuery(grid(1), checker, checker);
}

