@Test
public void testNullsInSearchRow() {
    executeSql("CREATE TABLE t(i1 INTEGER, i2 INTEGER) WITH TEMPLATE=REPLICATED ");
    executeSql("INSERT INTO t VALUES (0, null), (1, null), (2, 2), (3, null), (4, null)");
    executeSql("CREATE INDEX t_idx ON t(i1)");
    IgniteTable tbl = (IgniteTable) queryProcessor(grid(0)).schemaHolder().schema("PUBLIC").getTable("T");
    AtomicInteger filteredRows = new AtomicInteger();
    tbl.addIndex(new DelegatingIgniteIndex(tbl.getIndex("T_IDX")) {

        @Override
        public <Row> Iterable<Row> scan(ExecutionContext<Row> execCtx, ColocationGroup grp, Predicate<Row> filters, Supplier<Row> lowerIdxConditions, Supplier<Row> upperIdxConditions, Function<Row, Row> rowTransformer, @Nullable ImmutableBitSet requiredColumns) {
            Predicate<Row> filter = row -> {
                filteredRows.incrementAndGet();
                return true;
            };
            filters = filter.and(filters);
            return delegate.scan(execCtx, grp, filters, lowerIdxConditions, upperIdxConditions, rowTransformer, requiredColumns);
        }
    });
    String sql = "SELECT /*+ DISABLE_RULE('NestedLoopJoinConverter', 'MergeJoinConverter') */ t1.i1, t2.i1 " + "FROM t t1 " + "LEFT JOIN t t2 ON t1.i2 = t2.i1";
    assertQuery(sql).matches(QueryChecker.containsSubPlan("IgniteCorrelatedNestedLoopJoin")).matches(QueryChecker.containsIndexScan("PUBLIC", "T", "T_IDX")).returns(0, null).returns(1, null).returns(2, 2).returns(3, null).returns(4, null).check();
    // There shouldn't be full index scan in case of null values in search row, only one value must be found by
    // range scan and passed to predicate.
    assertEquals(1, filteredRows.get());
}

