    assertEquals(Period.ofMonths(5), eval("CAST('5' AS INTERVAL MONTHS)"));
    assertEquals(Period.ofYears(6), eval("CAST('6' AS INTERVAL YEARS)"));
    assertEquals(Period.of(1, 2, 0), eval("CAST('1-2' AS INTERVAL YEAR TO MONTH)"));
}

