    CountDownLatch scanLatch = new CountDownLatch(1);
    AtomicBoolean stop = new AtomicBoolean();
    IgniteCacheTable newTbl = new CacheTableImpl(srv.context(), oldTbl.descriptor()) {

        @Override
        public <Row> Iterable<Row> scan(ExecutionContext<Row> execCtx, ColocationGroup grp, Predicate<Row> filter, Function<Row, Row> rowTransformer, @Nullable ImmutableBitSet usedColumns) {
            return new Iterable<Row>() {

                @NotNull
                @Override
                public Iterator<Row> iterator() {
                    scanLatch.countDown();
                    return new Iterator<Row>() {

                        @Override
                        public boolean hasNext() {
                            // Produce rows until stopped.
                            return !stop.get();
                        }

                        @Override
                        public Row next() {
                            if (stop.get())
                                throw new NoSuchElementException();
                            return execCtx.rowHandler().factory().create();
                        }
                    };
                }
            };
        }
    };
    srvEngine.schemaHolder().schema("PUBLIC").add("PERSON", newTbl);
