        double allRowIsNullCnt = (nonNullableFields.contains(numericField)) ? (double) ROW_COUNT : 0.8125 * ROW_COUNT;
        double allRowRangeCnt = (nonNullableFields.contains(numericField)) ? (double) ROW_COUNT : 0.75 * ROW_COUNT;
        assertQuerySrv(String.format("select * from all_types where " + "%s > %d or %s < %d", numericField, -1, numericField, 101)).matches(QueryChecker.containsResultRowCount(allRowRangeCnt)).check();
        assertQuerySrv(String.format("select * from all_types where " + "%s > %d or %s < %d", numericField, 101, numericField, -1)).matches(QueryChecker.containsResultRowCount(1.)).check();
        assertQuerySrv(String.format("select * from all_types where " + "%s > %d or %s is null", numericField, -1, numericField)).matches(QueryChecker.containsResultRowCount(allRowIsNullCnt)).check();
        assertQuerySrv(String.format("select * from all_types where " + "%s > %d or %s is null", numericField, 101, numericField)).matches(QueryChecker.containsResultRowCount(nonNullableFields.contains(numericField) ? 1. : (double) ROW_COUNT * 0.25)).check();
    }
}

