/**
 * Test MERGE operator with aliases.
 */
@Test
public void testMergeAliases() {
    executeSql("CREATE TABLE test1 (a int, b int, c varchar)");
    executeSql("INSERT INTO test1 VALUES (0, 0, '0')");
    executeSql("CREATE TABLE test2 (a int, d int, e varchar)");
    // Without aliases, column 'A' in insert statement is not ambiguous.
    executeSql("MERGE INTO test2 USING test1 ON c = e " + "WHEN MATCHED THEN UPDATE SET d = b + 1" + "WHEN NOT MATCHED THEN INSERT (a, d, e) VALUES (a, b, c)");
    assertQuery("SELECT * FROM test2").returns(0, 0, "0").check();
    // Target table alias duplicate source table name.
    assertThrows("MERGE INTO test2 test1 USING test1 ON c = e " + "WHEN MATCHED THEN UPDATE SET d = b + 1", IgniteSQLException.class, "Duplicate relation name");
    // Source table alias duplicate target table name.
    assertThrows("MERGE INTO test2 USING test1 test2 ON c = e " + "WHEN MATCHED THEN UPDATE SET d = b + 1", IgniteSQLException.class, "Duplicate relation name");
    // Without aliases, reference columns by table name.
    executeSql("MERGE INTO test2 USING test1 ON test1.a = test2.a " + "WHEN MATCHED THEN UPDATE SET a = test1.a + 1");
    assertQuery("SELECT * FROM test2").returns(1, 0, "0").check();
    // Ambiguous column name in condition.
    assertThrows("MERGE INTO test2 USING test1 ON a = test1.a " + "WHEN MATCHED THEN UPDATE SET a = test1.a + 1", IgniteSQLException.class, "Column 'A' is ambiguous");
    // Ambiguous column name in update statement.
    assertThrows("MERGE INTO test2 USING test1 ON c = e " + "WHEN MATCHED THEN UPDATE SET a = a + 1", IgniteSQLException.class, "Column 'A' is ambiguous");
    // With aliases, reference columns by table alias.
    executeSql("MERGE INTO test2 test1 USING test1 test2 ON test1.d = test2.b " + "WHEN MATCHED THEN UPDATE SET a = test1.a + 1 " + "WHEN NOT MATCHED THEN INSERT (a, d, e) VALUES (test2.a, test2.b, test2.c)");
    assertQuery("SELECT * FROM test2").returns(2, 0, "0").check();
}

