/**
 * Tests correctness of fetch / offset params.
 */
@Test
public void testInvalidLimitOffset() {
    QueryEngine engine = engine(grid(0));
    String bigInt = BigDecimal.valueOf(10000000000L).toString();
    try {
        List<FieldsQueryCursor<List<?>>> cursors = engine.query(null, "PUBLIC", "SELECT * FROM TEST_REPL OFFSET " + bigInt + " ROWS");
        cursors.get(0).getAll();
        fail();
    } catch (Throwable e) {
        assertTrue(e.toString(), X.hasCause(e, "Illegal value of offset", SqlValidatorException.class));
    }
    try {
        List<FieldsQueryCursor<List<?>>> cursors = engine.query(null, "PUBLIC", "SELECT * FROM TEST_REPL FETCH FIRST " + bigInt + " ROWS ONLY");
        cursors.get(0).getAll();
        fail();
    } catch (Throwable e) {
        assertTrue(e.toString(), X.hasCause(e, "Illegal value of fetch / limit", SqlValidatorException.class));
    }
    try {
        List<FieldsQueryCursor<List<?>>> cursors = engine.query(null, "PUBLIC", "SELECT * FROM TEST_REPL LIMIT " + bigInt);
        cursors.get(0).getAll();
        fail();
    } catch (Throwable e) {
        assertTrue(e.toString(), X.hasCause(e, "Illegal value of fetch / limit", SqlValidatorException.class));
    }
    try {
        List<FieldsQueryCursor<List<?>>> cursors = engine.query(null, "PUBLIC", "SELECT * FROM TEST_REPL OFFSET -1 ROWS FETCH FIRST -1 ROWS ONLY");
        cursors.get(0).getAll();
        fail();
    } catch (Throwable e) {
        assertTrue(e.toString(), X.hasCause(e, IgniteSQLException.class));
    }
    try {
        List<FieldsQueryCursor<List<?>>> cursors = engine.query(null, "PUBLIC", "SELECT * FROM TEST_REPL OFFSET -1 ROWS");
        cursors.get(0).getAll();
        fail();
    } catch (Throwable e) {
        assertTrue(e.toString(), X.hasCause(e, IgniteSQLException.class));
    }
    try {
        List<FieldsQueryCursor<List<?>>> cursors = engine.query(null, "PUBLIC", "SELECT * FROM TEST_REPL OFFSET 2+1 ROWS");
        cursors.get(0).getAll();
        fail();
    } catch (Throwable e) {
        assertTrue(e.toString(), X.hasCause(e, IgniteSQLException.class));
    }
    // Check with parameters
    try {
        List<FieldsQueryCursor<List<?>>> cursors = engine.query(null, "PUBLIC", "SELECT * FROM TEST_REPL OFFSET ? ROWS FETCH FIRST ? ROWS ONLY", -1, -1);
        cursors.get(0).getAll();
        fail();
    } catch (Throwable e) {
        assertTrue(e.toString(), X.hasCause(e, "Illegal value of fetch / limit", SqlValidatorException.class));
    }
    try {
        List<FieldsQueryCursor<List<?>>> cursors = engine.query(null, "PUBLIC", "SELECT * FROM TEST_REPL OFFSET ? ROWS", -1);
        cursors.get(0).getAll();
        fail();
    } catch (Throwable e) {
        assertTrue(e.toString(), X.hasCause(e, "Illegal value of offset", SqlValidatorException.class));
    }
    try {
        List<FieldsQueryCursor<List<?>>> cursors = engine.query(null, "PUBLIC", "SELECT * FROM TEST_REPL FETCH FIRST ? ROWS ONLY", -1);
        cursors.get(0).getAll();
        fail();
    } catch (Throwable e) {
        assertTrue(e.toString(), X.hasCause(e, "Illegal value of fetch / limit", SqlValidatorException.class));
    }
}

