/**
 */
@Test
public void testCollationPassThrough() throws Exception {
    IgniteSchema publicSchema = createSchema(createTable("TEST", IgniteDistributions.single(), "A", Integer.class, "B", Integer.class));
    // Sort order equals to grouping set.
    assertPlan("SELECT a, b, COUNT(*) FROM test GROUP BY a, b ORDER BY a, b", publicSchema, isInstanceOf(IgniteAggregate.class).and(input(isInstanceOf(IgniteSort.class).and(s -> s.collation().equals(TraitUtils.createCollation(F.asList(0, 1)))).and(input(isTableScan("TEST"))))), HASH_AGG_RULES);
    // Sort order equals to grouping set (permuted collation).
    assertPlan("SELECT a, b, COUNT(*) FROM test GROUP BY a, b ORDER BY b, a", publicSchema, isInstanceOf(IgniteAggregate.class).and(input(isInstanceOf(IgniteSort.class).and(s -> s.collation().equals(TraitUtils.createCollation(F.asList(1, 0)))).and(input(isTableScan("TEST"))))), HASH_AGG_RULES);
    // Sort order is a subset of grouping set.
    assertPlan("SELECT a, b, COUNT(*) cnt FROM test GROUP BY a, b ORDER BY a", publicSchema, isInstanceOf(IgniteAggregate.class).and(input(isInstanceOf(IgniteSort.class).and(s -> s.collation().equals(TraitUtils.createCollation(F.asList(0, 1)))).and(input(isTableScan("TEST"))))), HASH_AGG_RULES);
    // Sort order is a subset of grouping set (permuted collation).
    assertPlan("SELECT a, b, COUNT(*) cnt FROM test GROUP BY a, b ORDER BY b", publicSchema, isInstanceOf(IgniteAggregate.class).and(input(isInstanceOf(IgniteSort.class).and(s -> s.collation().equals(TraitUtils.createCollation(F.asList(1, 0)))).and(input(isTableScan("TEST"))))), HASH_AGG_RULES);
    // Sort order is a superset of grouping set (additional sorting required).
    assertPlan("SELECT a, b, COUNT(*) cnt FROM test GROUP BY a, b ORDER BY a, b, cnt", publicSchema, isInstanceOf(IgniteSort.class).and(s -> s.collation().equals(TraitUtils.createCollation(F.asList(0, 1, 2)))).and(input(isInstanceOf(IgniteAggregate.class).and(input(isInstanceOf(IgniteSort.class).and(s -> s.collation().equals(TraitUtils.createCollation(F.asList(0, 1)))).and(input(isTableScan("TEST"))))))), HASH_AGG_RULES);
    // Sort order is not equals to grouping set (additional sorting required).
    assertPlan("SELECT a, b, COUNT(*) cnt FROM test GROUP BY a, b ORDER BY cnt, b", publicSchema, isInstanceOf(IgniteSort.class).and(s -> s.collation().equals(TraitUtils.createCollation(F.asList(2, 1)))).and(input(isInstanceOf(IgniteAggregate.class).and(input(isInstanceOf(IgniteSort.class).and(s -> s.collation().equals(TraitUtils.createCollation(F.asList(0, 1)))).and(input(isTableScan("TEST"))))))), HASH_AGG_RULES);
}

/**
 * Check equi-join on not colocated fields.
 * CorrelatedNestedLoopJoinTest is applicable for this case only with IndexSpool.
 */
@Test
public void testNotColocatedEqJoin() throws Exception {
    IgniteSchema publicSchema = new IgniteSchema("PUBLIC");
    IgniteTypeFactory f = new IgniteTypeFactory(IgniteTypeSystem.INSTANCE);
    publicSchema.addTable("T0", new TestTable(new RelDataTypeFactory.Builder(f).add("ID", f.createJavaType(Integer.class)).add("JID", f.createJavaType(Integer.class)).add("VAL", f.createJavaType(String.class)).build()) {

        @Override
        public IgniteDistribution distribution() {
            return IgniteDistributions.affinity(0, "T0", "hash");
        }
    }.addIndex("t0_jid_idx", 1, 0));
    publicSchema.addTable("T1", new TestTable(new RelDataTypeFactory.Builder(f).add("ID", f.createJavaType(Integer.class)).add("JID", f.createJavaType(Integer.class)).add("VAL", f.createJavaType(String.class)).build()) {

        @Override
        public IgniteDistribution distribution() {
            return IgniteDistributions.affinity(0, "T1", "hash");
        }
    }.addIndex("t1_jid_idx", 1, 0));
    String sql = "select * " + "from t0 " + "join t1 on t0.jid = t1.jid";
    IgniteRel phys = physicalPlan(sql, publicSchema, "MergeJoinConverter", "NestedLoopJoinConverter", "FilterSpoolMergeToHashIndexSpoolRule");
    checkSplitAndSerialization(phys, publicSchema);
    IgniteSortedIndexSpool idxSpool = findFirstNode(phys, byClass(IgniteSortedIndexSpool.class));
    List<RexNode> lBound = idxSpool.indexCondition().lowerBound();
    assertNotNull(lBound);
    assertEquals(3, lBound.size());
    assertNull(lBound.get(0));
    assertTrue(lBound.get(1) instanceof RexFieldAccess);
    assertNull(lBound.get(2));
    List<RexNode> uBound = idxSpool.indexCondition().upperBound();
    assertNotNull(uBound);
    assertEquals(3, uBound.size());
    assertNull(uBound.get(0));
    assertTrue(uBound.get(1) instanceof RexFieldAccess);
    assertNull(uBound.get(2));
}

