    checkQuery("SELECT NAME FROM products d WHERE CAT_ID > 1;").matches(containsAnyScan("PUBLIC", "PRODUCTS")).matches(containsProject("PUBLIC", "PRODUCTS", 4, 7)).returns("noname2").returns("noname3").returns("noname4").check();
