/**
 * Tests projects with nested requests.
 */
@Test
public void testNestedProjects() {
    checkQuery("SELECT NAME FROM products WHERE CAT_ID IN (SELECT CAT_ID FROM products WHERE CAT_ID > 1) and ID > 2;").matches(containsAnyProject("PUBLIC", "PRODUCTS")).returns("noname3").returns("noname4").check();
    checkQuery("SELECT NAME FROM products WHERE CAT_ID IN (SELECT DISTINCT CAT_ID FROM products WHERE CAT_ID > 1)").matches(containsAnyProject("PUBLIC", "PRODUCTS")).returns("noname2").returns("noname3").returns("noname4").check();
    checkQuery("SELECT NAME FROM products WHERE CAT_ID IN (SELECT DISTINCT CAT_ID FROM products WHERE SUBCAT_ID > 11)").matches(containsAnyProject("PUBLIC", "PRODUCTS")).returns("noname3").returns("noname4").check();
    checkQuery("SELECT NAME FROM products WHERE CAT_ID = (SELECT CAT_ID FROM products WHERE SUBCAT_ID = 13)").matches(containsAnyProject("PUBLIC", "PRODUCTS")).returns("noname4").check();
    GridTestUtils.assertThrowsWithCause(() -> checkQuery("SELECT NAME FROM products WHERE CAT_ID = (SELECT CAT_ID FROM products WHERE SUBCAT_ID = 11)").check(), IllegalArgumentException.class);
    GridTestUtils.assertThrowsWithCause(() -> checkQuery("SELECT NAME FROM products WHERE CAT_ID = (SELECT 2 UNION ALL SELECT 1)").check(), IllegalArgumentException.class);
    GridTestUtils.assertThrowsWithCause(() -> checkQuery("SELECT NAME FROM products WHERE CAT_ID = (SELECT null UNION ALL SELECT 1)").check(), IllegalArgumentException.class);
}

