/**
 * @throws Exception If failed.
 */
@Test
public void testMultithreadedTaskRun() throws Exception {
    final AtomicLong cnt = new AtomicLong();
    final AtomicReference<GridClientException> err = new AtomicReference<>();
    final ConcurrentLinkedQueue<String> execQueue = new ConcurrentLinkedQueue<>();
    IgniteInternalFuture<?> fut = multithreadedAsync(new Runnable() {

        @Override
        public void run() {
            long processed;
            while ((processed = cnt.getAndIncrement()) < taskExecutionCount()) {
                try {
                    if (processed > 0 && processed % STATISTICS_PRINT_STEP == 0)
                        info(">>>>>>> " + processed + " tasks finished.");
                    String res = client.compute().execute(TestTask.class.getName(), null);
                    execQueue.add(res);
                } catch (GridClientException e) {
                    err.compareAndSet(null, e);
                }
            }
        }
    }, THREAD_CNT, "client-task-request");
    fut.get();
    if (err.get() != null)
        throw new Exception(err.get());
    assertEquals(taskExecutionCount(), execQueue.size());
    // With round-robin balancer each node must receive equal count of task requests.
    Collection<String> executionIds = new HashSet<>(execQueue);
    assertTrue(executionIds.size() == NODES_CNT);
    Map<String, AtomicInteger> statisticsMap = new HashMap<>();
    for (String id : executionIds) statisticsMap.put(id, new AtomicInteger());
    for (String id : execQueue) statisticsMap.get(id).incrementAndGet();
    info(">>>>>>> Execution statistics per node:");
    for (Map.Entry<String, AtomicInteger> e : statisticsMap.entrySet()) info(">>>>>>> " + e.getKey() + " run " + e.getValue().get() + " tasks");
}

/**
 * Json format string in cache should not transform to Json object on get request.
 */
@Test
public void testSkipString2JsonTransformation() throws Exception {
    String val = "{\"v\":\"my Value\",\"t\":1422559650154}";
    // Put to cache JSON format string value.
    String ret = content(F.asMap("cmd", GridRestCommand.CACHE_PUT.key(), "cacheName", LOCAL_CACHE, "key", "a", "val", URLEncoder.encode(val, CHARSET)));
    JsonNode res = jsonResponse(ret);
    assertEquals("Incorrect put response", true, res.asBoolean());
    // Escape '\' symbols disappear from response string on transformation to JSON object.
    ret = content(F.asMap("cmd", GridRestCommand.CACHE_GET.key(), "cacheName", LOCAL_CACHE, "key", "a"));
    res = jsonResponse(ret);
    assertEquals("Incorrect get response", val, res.asText());
}

/**
 * @throws Exception If failed.
 */
@Test
public void testNoFailedReconnection() throws Exception {
    for (int i = 0; i < SERVERS_CNT; i++) runServer(i, false);
    try (GridClient client = client()) {
        // Here client opens initial connection and fetches topology.
        // Only first server in list should be contacted.
        assertEquals(1, srvs[0].getConnectCount());
        for (int i = 1; i < SERVERS_CNT; i++) assertEquals(0, srvs[i].getConnectCount());
        srvs[0].resetCounters();
        int contactedSrv = 0;
        for (int i = 0; i < 100; i++) {
            int failed = contactedSrv;
            srvs[failed].fail();
            // Sometimes session close missing on client side. Retry few times until request succeeds.
            while (true) try {
                client.compute().refreshTopology(false, false);
                break;
            } catch (GridClientConnectionResetException e) {
                info("Exception caught: " + e);
            }
            // Check which servers where contacted,
            int connects = 0;
            for (int srv = 0; srv < SERVERS_CNT; srv++) {
                if (srvs[srv].getSuccessfulConnectCount() > 0) {
                    assertTrue("Failed server was contacted: " + srv, srv != failed);
                    contactedSrv = srv;
                }
                connects += srvs[srv].getSuccessfulConnectCount();
            }
            // Only one new connection should be opened.
            assertEquals(1, connects);
            srvs[failed].repair();
            // It should be the only server with non-0 counters.
            srvs[contactedSrv].resetCounters();
        }
    }
}

