 * @throws Exception If failed.
 */
@Ignore("https://issues.apache.org/jira/browse/IGNITE-590")
@Test
public void testIdleConnection() throws Exception {
    // TODO: IGNITE-590 it may be wrong value. Need to investigate after IGNITE-590 will be fixed.
    int srvsCnt = 4;
    for (int i = 0; i < srvsCnt; i++) runServer(i, false);
    // Here client opens initial connection and fetches topology.
    GridClient client = client();
    try {
        // Only first server in list should be contacted.
        assertEquals(1, srvs[0].getConnectCount());
        // Timeout as idle.
        Thread.sleep(35000);
        assertEquals(1, srvs[0].getDisconnectCount());
        for (int i = 1; i < srvsCnt; i++) assertEquals(0, srvs[i].getConnectCount());
        srvs[0].resetCounters();
        // On new request connection should be re-opened.
        client.compute().refreshTopology(false, false);
        assertEquals(1, srvs[0].getConnectCount());
        for (int i = 1; i < srvsCnt; i++) assertEquals(0, srvs[i].getConnectCount());
    } finally {
        GridClientFactory.stop(client.id());
    }
}

