    info("Get command result: " + ret);
    checkJson(ret, p);
    // Test with SQL.
    SqlFieldsQuery qry = new SqlFieldsQuery("create table employee(id integer primary key, name varchar(100), salary integer);" + "insert into employee(id, name, salary) values (1, 'Alex', 300);");
    grid(0).context().query().querySqlFields(qry, true, false);
    ret = content("SQL_PUBLIC_EMPLOYEE", GridRestCommand.CACHE_GET, "keyType", "int", "key", "1");
    info("Get command result: " + ret);
    JsonNode res = assertResponseSucceeded(ret, false);
    assertEquals("Alex", res.get("NAME").asText());
    assertEquals(300, res.get("SALARY").asInt());
    // Test with circular reference.
    CircularRef ref1 = new CircularRef(1, "Alex");
    CircularRef ref2 = new CircularRef(2, "300");
    CircularRef ref3 = new CircularRef(3, "220");
    ref1.ref(ref2);
    jcache().put(220, ref1);
    ret = content(DEFAULT_CACHE_NAME, GridRestCommand.CACHE_GET, "keyType", "int", "key", "220");
    info("Get command result: " + ret);
    JsonNode json = assertResponseSucceeded(ret, false);
    assertEquals(ref1.name, json.get("name").asText());
    assertEquals(ref1.ref.toString(), json.get("ref").toString());
    ref2.ref(ref1);
    jcache().put(222, ref1);
    ret = content(DEFAULT_CACHE_NAME, GridRestCommand.CACHE_GET, "keyType", "int", "key", "222");
    info("Get command result: " + ret);
    assertResponseContainsError(ret, "Failed convert to JSON object for circular references");
    ref1.ref(ref2);
    ref2.ref(ref3);
    ref3.ref(ref1);
    jcache().put(223, ref1);
    ret = content(DEFAULT_CACHE_NAME, GridRestCommand.CACHE_GET, "keyType", "int", "key", "223");
    info("Get command result: " + ret);
    assertResponseContainsError(ret, "Failed convert to JSON object for circular references");
}

