        execute(c, "CREATE TABLE Company(id int primary key, name varchar) WITH " + "\"template=replicated,cache_name=Company\"");
        execute(c, "CREATE TABLE Person(id int primary key, name varchar, companyid int) WITH " + "\"template=replicated,cache_name=Person\"");
        execute(c, "insert into Company(id, name) values (1, 'Apple')");
        execute(c, "insert into Person(id, name, companyid) values (2, 'John', 1)");
        List<List<?>> res = execute(c, "SELECT p.id, p.name, c.name from Person p left join Company c on " + "p.companyid = c.id");
        assertEqualsCollections(F.asList(2, "John", "Apple"), res.get(0));
