    assert !rs.isBeforeFirst();
    assert !rs.isAfterLast();
    assert rs.isFirst();
    assert !rs.isLast();
    assert rs.getRow() == 1;
    assert rs.next();
    assert !rs.isBeforeFirst();
    assert !rs.isAfterLast();
    assert !rs.isFirst();
    assert rs.isLast();
    assert rs.getRow() == 2;
    assert !rs.next();
    assert !rs.isBeforeFirst();
    assert rs.isAfterLast();
    assert !rs.isFirst();
    assert !rs.isLast();
    assert rs.getRow() == 0;
    rs = stmt.executeQuery("select id from TestObject where id < 0");
    assert !rs.isBeforeFirst();
}

