    cmdArgs.put(WAL, asList(new String[] { "print" }, new String[] { "delete" }));
    cmdArgs.put(METADATA, asList(new String[] { "help" }, new String[] { "list" }));
    cmdArgs.put(TRACING_CONFIGURATION, Collections.singletonList(new String[] { "get_all" }));
