        int i = cacheSize;
        for (; i < cacheSize + (ENTRY_CNT - 10); i++) streamer.addData(i, i);
        for (; i < cacheSize + ENTRY_CNT; i++) streamer.addData(i, null);
        streamer.flush();
    }
    execVIWithNoErrCheck(cacheName, false);
    execVIWithNoErrCheck(cacheName, true);
}

