    int[] typeIds = new int[cnt];
    repeat(cnt, i -> typeIds[i] = crd.binary().builder(typeNames[i]).setField("fld0", typeValues[i]).build().type().typeId());
    Path[] typeBackups = new Path[typeNames.length];
    try {
        repeat(cnt, i -> {
