@Test
public void testComplexCompatibilityInMemory() throws Exception {
    persistenceEnabled = false;
    additionalMemRegion = false;
    IgniteEx crd = startGrid(0);
    IgnitePredicate<ClusterNode> filter0 = n -> Stream.of("0", "1").anyMatch(k -> n.consistentId().toString().endsWith(k));
    IgnitePredicate<ClusterNode> filter1 = n -> Stream.of("0", "1", "2").anyMatch(k -> n.consistentId().toString().endsWith(k));
    IgnitePredicate<ClusterNode> filter2 = n -> Stream.of("0", "1", "3").anyMatch(k -> n.consistentId().toString().endsWith(k));
    final String cache0Name = "cache0";
    IgniteCache<Object, Object> cache0 = crd.getOrCreateCache(new CacheConfiguration<>(cache0Name).setBackups(1).setNodeFilter(filter0));
    for (int i = 0; i < 1024; i++) cache0.put(i, i);
    // Trigger rebalancing.
    IgniteConfiguration cfg1 = getConfiguration(getTestIgniteInstanceName(1));
    TestRecordingCommunicationSpi spi2 = (TestRecordingCommunicationSpi) cfg1.getCommunicationSpi();
    spi2.blockMessages(TestRecordingCommunicationSpi.blockDemandMessageForGroup(CU.cacheId(cache0Name)));
    GridTestUtils.runAsync(new Callable<Void>() {

        @Override
        public Void call() throws Exception {
            startGrid(cfg1);
            return null;
        }
    });
    spi2.waitForBlocked();
    // Compatible event.
    startGrid(2);
    // Compatible event.
    startGrid(3);
    awaitPartitionMapExchange(false, false, null, false, new HashSet<>(Arrays.asList("cache1", "cache2")));
    // Compatible event.
    final String cache1Name = "cache1";
    IgniteCache<Object, Object> cache1 = crd.getOrCreateCache(new CacheConfiguration<>(cache1Name).setBackups(1).setNodeFilter(filter1));
    // Compatible event.
    final String cache2Name = "cache2";
    IgniteCache<Object, Object> cache2 = crd.getOrCreateCache(new CacheConfiguration<>(cache2Name).setBackups(1).setNodeFilter(filter2));
    for (int i = 0; i < 1024; i++) {
        cache1.put(i, i);
        cache2.put(i, i);
    }
    // Compatible event.
    stopGrid(2);
    // Compatible event.
    stopGrid(3);
    spi2.stopBlock();
    awaitPartitionMapExchange();
}

