        Assert.assertArrayEquals(expArr, deserializeEnumBinaryArray(enumObj.field("testEnumArr")));
        Assert.assertArrayEquals(expArr, ((TestClsWithEnum) enumObj.deserialize()).testEnumArr);
    } finally {
        clearBinaryMeta();
    }
}

