        if (node0.context().encryption().groupKeyIds(grpId1).size() == 1 && node1.context().encryption().groupKeyIds(grpId1).size() == 1 && node0.context().encryption().groupKeyIds(grpId2).size() == 1 && node1.context().encryption().groupKeyIds(grpId2).size() == 1)
