        assert false;
    } catch (Exception e) {
        assert e instanceof IllegalStateException : "Wrong exception type.";
    }
    try {
        ignite.cluster().forRemotes();
        assert false;
    } catch (Exception e) {
        assert e instanceof IllegalStateException : "Wrong exception type.";
    }
    try {
        ignite.compute().localTasks();
        assert false;
    } catch (Exception e) {
        assert e instanceof IllegalStateException : "Wrong exception type.";
    }
    //check all executors are terminated
    GridKernalContext ctx = ignite.context();
    Map<String, ExecutorService> executors = Arrays.stream(GridKernalContext.class.getMethods()).filter(method -> method.getReturnType().equals(ExecutorService.class)).collect(HashMap::new, (map, method) -> {
        try {
            String mtdName = method.getName();
            String executorSvcKey = mtdName.startsWith("get") ? mtdName.substring(3) : mtdName;
            map.put(executorSvcKey, (ExecutorService) method.invoke(ctx));
        } catch (IllegalAccessException | InvocationTargetException e) {
            throw new IgniteException(e);
        }
    }, HashMap::putAll);
    String errs = executors.entrySet().stream().filter(e -> !(e.getValue() == null || e.getValue().isTerminated())).map(e -> e.getKey() + " not terminated.").collect(Collectors.joining("\n"));
    assertTrue(errs, errs == null || errs.isEmpty());
}

