/**
 * Test GridAffinityAssignment logic when backup threshold is not reached.
 */
@Test
public void testPrimaryBackupPartitions() {
    GridAffinityAssignment gridAffinityAssignment = new GridAffinityAssignment(new AffinityTopologyVersion(1, 0), Arrays.asList(Arrays.asList(clusterNode1, clusterNode2, clusterNode3, clusterNode4), Arrays.asList(clusterNode1, clusterNode2, clusterNode3, clusterNode4), Arrays.asList(clusterNode5, clusterNode6)), new ArrayList<>());
    GridAffinityAssignmentV2 gridAffinityAssignment2 = new GridAffinityAssignmentV2(new AffinityTopologyVersion(1, 0), Arrays.asList(Arrays.asList(clusterNode1, clusterNode2, clusterNode3, clusterNode4), Arrays.asList(clusterNode1, clusterNode2, clusterNode3, clusterNode4), Arrays.asList(clusterNode5, clusterNode6)), new ArrayList<>());
    assertPartitions(gridAffinityAssignment);
    assertPartitions(gridAffinityAssignment2);
    if (AffinityAssignment.IGNITE_DISABLE_AFFINITY_MEMORY_OPTIMIZATION)
        assertSame(gridAffinityAssignment2.getIds(0), gridAffinityAssignment2.getIds(0));
    else
        assertNotSame(gridAffinityAssignment2.getIds(0), gridAffinityAssignment2.getIds(0));
    try {
        gridAffinityAssignment2.primaryPartitions(clusterNode1.id()).add(1000);
        fail("Unmodifiable exception expected");
    } catch (UnsupportedOperationException ignored) {
        // Ignored.
    }
    try {
        gridAffinityAssignment2.backupPartitions(clusterNode1.id()).add(1000);
        fail("Unmodifiable exception expected");
    } catch (UnsupportedOperationException ignored) {
        // Ignored.
    }
    Set<Integer> unwrapped = U.field(gridAffinityAssignment2.primaryPartitions(clusterNode1.id()), "delegate");
    if (AffinityAssignment.IGNITE_DISABLE_AFFINITY_MEMORY_OPTIMIZATION)
        assertTrue(unwrapped instanceof HashSet);
    else
        assertTrue(unwrapped instanceof BitSetIntSet);
}

