        if (!primaryNode.equals(primaryIgnite.cluster().localNode())) {
            log.info("Update from new primary: " + primary.name());
            primary = grid(primaryNode);
            gotNewPrimary = true;
            primary.cache(DEFAULT_CACHE_NAME).put(key, 2);
