    awaitPartitionMapExchange();
    // Invalid for writing due to partitions loss.
    assertCacheStatus(CACHE_NAME_1, false, false);
    // Invalid for writing due to invalid topology.
    assertCacheStatus(CACHE_NAME_2, true, false);
}

