    List<IgniteInternalFuture<?>> futs = new ArrayList<>();
    final AtomicBoolean countedDown = new AtomicBoolean();
    CountDownLatch allLatchesObtained = new CountDownLatch(gridCount());
    for (int i = 0; i < gridCount(); i++) {
