                int nodeIdx = startIdx.incrementAndGet();
                if (rnd.nextInt(3) == 0) {
                    log.info("Start client: " + nodeIdx);
                    startClientGrid(nodeIdx);
                } else {
                    log.info("Start server: " + nodeIdx);
                    startGrid(nodeIdx);
                }
                if (rnd.nextBoolean()) {
                    log.info("Stop started node: " + nodeIdx);
                    stopGrid(nodeIdx);
