    TestRecordingCommunicationSpi spi0 = (TestRecordingCommunicationSpi) ignite0.configuration().getCommunicationSpi(), spi2, spi3;
    // Prevent exchange completion.
    spi0.blockMessages(GridDhtPartitionsFullMessage.class, ignite2.name());
