        f2 = cache2.getAndRemoveAsync("async1");
        assert "asyncval1".equals(f2.get());
        assert latch.await(5, SECONDS);
        f1 = cache1.getAsync("async1");
        f2 = cache2.getAsync("async1");
        f3 = cache3.getAsync("async1");
