        v2 = f2.get();
        v3 = f3.get();
        info("Removed v1: " + v1);
        info("Removed v2: " + v2);
        info("Removed v3: " + v3);
        assert v1 == null;
        assert v2 == null;
        assert v3 == null;
    } finally {
        ignite1.events().stopLocalListen(lsnr);
        ignite2.events().stopLocalListen(lsnr);
        ignite3.events().stopLocalListen(lsnr);
    }
}

