/**
 */
@Test
public void testLateAffinityAssignmentOnBackupLeftAndJoin() throws Exception {
    String cacheName = "single-partitioned";
    cacheC = new IgniteClosure<String, CacheConfiguration<?, ?>[]>() {

        @Override
        public CacheConfiguration<?, ?>[] apply(String igniteInstanceName) {
            CacheConfiguration<?, ?> ccfg = new CacheConfiguration<>();
            ccfg.setName(cacheName);
            ccfg.setAffinity(new Map1PartitionTo2NodesAffinityFunction());
            return new CacheConfiguration[] { ccfg };
        }
    };
    persistence = true;
    try {
        // Primary partition holder.
        startGrid(0);
        // Backup partition holder.
        startGrid(1);
        grid(0).cluster().active(true);
        // Stopping backup partition holder.
        grid(1).close();
        // Updating primary partition to cause rebalance.
        grid(0).getOrCreateCache(cacheName).put(1, 1);
        // Restarting backup partition holder.
        startGrid(1);
        awaitPartitionMapExchange();
        AffinityTopologyVersion topVer = grid(0).context().discovery().topologyVersionEx();
        assertEquals(topVer.topologyVersion(), 4);
        // LAA happen on backup partition holder restart.
        assertEquals(topVer.minorTopologyVersion(), 1);
        GridDhtPartitionsExchangeFuture fut4 = null;
        GridDhtPartitionsExchangeFuture fut41 = null;
        for (GridDhtPartitionsExchangeFuture fut : grid(0).context().cache().context().exchange().exchangeFutures()) {
            AffinityTopologyVersion ver = fut.topologyVersion();
            if (ver.topologyVersion() == 4) {
                if (ver.minorTopologyVersion() == 0)
                    fut4 = fut;
                else if (ver.minorTopologyVersion() == 1)
                    fut41 = fut;
            }
        }
        // Backup partition holder restart cause non-rebalanced state.
        assertFalse(fut4.rebalanced());
        // LAA.
        assertTrue(fut41.rebalanced());
    } finally {
        persistence = false;
    }
}

/**
 * Test for transaction starting in one thread, continuing in another.
 *
 * @throws Exception If failed.
 */
@Test
public void testResumeTxInAnotherThread() throws Exception {
    executeTestForAllCaches(new CI2Exc<Ignite, IgniteCache<Integer, Integer>>() {

        @Override
        public void applyx(Ignite ignite, final IgniteCache<Integer, Integer> cache) throws Exception {
            for (TransactionIsolation isolation : TransactionIsolation.values()) {
                final Transaction tx = ignite.transactions().txStart(transactionConcurrency(), isolation);
                final AtomicInteger cntr = new AtomicInteger(0);
                for (int j = -1; j > -10; j--) cache.put(j, j);
                cache.put(cntr.get(), cntr.getAndIncrement());
                tx.suspend();
                assertEquals(SUSPENDED, tx.state());
                assertNull("Thread already have tx", ignite.transactions().tx());
                assertNull(cache.get(-1));
                assertNull(cache.get(cntr.get()));
                for (int i = 0; i < 10; i++) {
                    GridTestUtils.runAsync(() -> {
                        assertEquals(SUSPENDED, tx.state());
                        tx.resume();
                        assertEquals(ACTIVE, tx.state());
                        for (int j = -1; j > -10; j--) cache.put(j, j);
                        cache.put(cntr.get(), cntr.getAndIncrement());
                        tx.suspend();
                    }).get(FUT_TIMEOUT);
                }
                tx.resume();
                for (int j = -1; j > -10; j--) cache.remove(j);
                tx.commit();
                assertEquals(COMMITTED, tx.state());
                for (int i = 0; i < cntr.get(); i++) assertEquals(i, (int) cache.get(i));
                assertFalse(cache.containsKey(-1));
                cache.removeAll();
            }
        }
    });
}

