@Test
public void testCrossCacheTxInAnotherThread() throws Exception {
    executeTestForAllCaches(new CI2Exc<Ignite, IgniteCache<Integer, Integer>>() {

        @Override
        public void applyx(Ignite ignite, final IgniteCache<Integer, Integer> cache) throws Exception {
            // TODO: IGNITE-9110 Optimistic tx hangs in cross-cache operations with LOCAL and non LOCAL caches.
            if (transactionConcurrency() == TransactionConcurrency.OPTIMISTIC && cache.getConfiguration(CacheConfiguration.class).getCacheMode() == LOCAL)
                return;
            for (TransactionIsolation isolation : TransactionIsolation.values()) {
