            } catch (GridCacheEntryRemovedException ignored) {
                return true;
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }
    }, 5000);
    // Node 1 still has node2 in readers map.
    assertFalse(((GridDhtCacheEntry) dht(cache1).entryEx(1)).readers().contains(n2.id()));
