        GridCacheEntryEx e2 = cacheAdapter2.entryEx(1);
        assertNotNull(e2);
        assertNotSame(e2, e1);
        e2.unswap();
        assertNotNull(e2.version());
        assertEquals(e1.version(), e2.version());
    } finally {
