/**
 * @throws Exception In case of error.
 */
@Test
public void testClear() throws Exception {
    IgniteCache<String, Integer> cache = jcache();
    Set<String> keys = new HashSet<>(primaryKeysForCache(cache, 3));
    for (String key : keys) assertNull(cache.get(key));
    Map<String, Integer> vals = new HashMap<>(keys.size());
    int i = 0;
    for (String key : keys) {
        cache.put(key, i);
        vals.put(key, i);
        i++;
    }
    for (String key : keys) assertEquals(vals.get(key), peek(cache, key));
    cache.clear();
    for (String key : keys) assertNull(peek(cache, key));
    for (i = 0; i < gridCount(); i++) jcache(i).clear();
    for (i = 0; i < gridCount(); i++) assert jcache(i).localSize() == 0;
    for (Map.Entry<String, Integer> entry : vals.entrySet()) cache.put(entry.getKey(), entry.getValue());
    for (String key : keys) assertEquals(vals.get(key), peek(cache, key));
    String first = F.first(keys);
    if (lockingEnabled()) {
        Lock lock = cache.lock(first);
        lock.lock();
        try {
            cache.clear();
            GridCacheContext<String, Integer> cctx = context(0);
            GridCacheEntryEx entry = cctx.isNear() ? cctx.near().dht().peekEx(first) : cctx.cache().peekEx(first);
            assertNotNull(entry);
        } finally {
            lock.unlock();
        }
    } else {
        cache.clear();
        cache.put(first, vals.get(first));
    }
    cache.clear();
    assert cache.localSize() == 0 : "Values after clear.";
    i = 0;
    for (String key : keys) {
        cache.put(key, i);
        vals.put(key, i);
        i++;
    }
    cache.put("key1", 1);
    cache.put("key2", 2);
    cache.localEvict(Sets.union(ImmutableSet.of("key1", "key2"), keys));
    assert cache.localSize(ONHEAP) == 0;
    cache.clear();
    assert cache.localPeek("key1", ONHEAP) == null;
    assert cache.localPeek("key2", ONHEAP) == null;
}

