        for (int i = 0; i < keys.length; i++) {
            while (true) {
                key++;
                if (grid(0).affinity(DEFAULT_CACHE_NAME).mapKeyToNode(key).equals(grid(0).localNode())) {
                    if (i > 0)
                        jcache(0).put(key, new Value(new byte[i * 1024]));
                    keys[i] = key;
                    break;
                }
            }
        }
        // Create near entries.
        assertNotNull(jcache(1).get(keys[1]));
        assertNotNull(jcache(1).get(keys[2]));
        GridCacheAdapter<Object, Object> cache0 = dht(jcache(0));
        // Values are unswapped, so value size should be included in cache entry size
        assertEquals(KEY_SIZE + NULL_REF_SIZE + ENTRY_OVERHEAD + DHT_ENTRY_OVERHEAD + extrasSize(cache0.entryEx(keys[0])), cache0.entryEx(keys[0]).memorySize());
        assertEquals(KEY_SIZE + ONE_KB_VAL_SIZE + ENTRY_OVERHEAD + DHT_ENTRY_OVERHEAD + READER_SIZE + extrasSize(cache0.entryEx(keys[1])), cache0.entryEx(keys[1]).memorySize());
        assertEquals(KEY_SIZE + TWO_KB_VAL_SIZE + ENTRY_OVERHEAD + DHT_ENTRY_OVERHEAD + READER_SIZE + extrasSize(cache0.entryEx(keys[2])), cache0.entryEx(keys[2]).memorySize());
        GridCacheAdapter<Object, Object> cache1 = near(jcache(1));
        assertEquals(KEY_SIZE + NULL_REF_SIZE + ENTRY_OVERHEAD + NEAR_ENTRY_OVERHEAD + extrasSize(cache1.entryEx(keys[0])), cache1.entryEx(keys[0]).memorySize());
        assertEquals(KEY_SIZE + ONE_KB_VAL_SIZE + ENTRY_OVERHEAD + NEAR_ENTRY_OVERHEAD + extrasSize(cache1.entryEx(keys[1])), cache1.entryEx(keys[1]).memorySize());
        assertEquals(KEY_SIZE + TWO_KB_VAL_SIZE + ENTRY_OVERHEAD + NEAR_ENTRY_OVERHEAD + extrasSize(cache1.entryEx(keys[2])), cache1.entryEx(keys[2]).memorySize());
    } finally {
        ignite(0).destroyCache(cache.getName());
    }
}

