        ccfg.setName("cfg-" + i);
        ignite.addCacheConfiguration(ccfg);
    }
    boolean evt = evtLatch.await(3000, TimeUnit.MILLISECONDS);
    assertFalse(evt);
    log.info("Start cache.");
    checkGetOrCreate(ignite(0), "cfg-0", 0);
    evt = evtLatch.await(3000, TimeUnit.MILLISECONDS);
    assertFalse(evt);
}

