                latch1.countDown();
                info("Let thread2 proceed.");
                cache.put(1, "1");
                info("Put 1='1' key pair into cache.");
                latch2.await();
                info("Waited for latch 2");
            } finally {
                lock.unlock();
                info("Unlocked entry for key 1.");
                latch3.countDown();
            }
            return null;
        }
    });
    GridTestThread t2 = new GridTestThread(new Callable<Object>() {

