            assert cache.isLocalLocked(1, false);
            assert !cache.isLocalLocked(1, true);
            info("Tried to lock cache for key1");
            latch2.countDown();
            info("Released latch2");
            latch3.await();
            assert lock.tryLock();
            assert cache.isLocalLocked(1, false);
            assert cache.isLocalLocked(1, true);
            try {
                info("Locked cache for key 1");
                assert "1".equals(cache.get(1));
                info("Read value for key 1");
