                info("Removed value for key 1");
                assert cache.isLocalLocked(1, false);
                assert cache.isLocalLocked(1, true);
                info("Checked that cache is locked for key 1");
            } finally {
                lock.unlock();
                info("Unlocked cache for key 1");
            }
            assert !cache.isLocalLocked(1, false);
            assert !cache.isLocalLocked(1, true);
            return null;
        }
    });
    t1.start();
