            for (Integer key : keys2) {
                boolean locked = cache.isLocalLocked(key, false);
                assert locked == keys1.contains(key) : "Lock failure for key [key=" + key + ", locked=" + locked + ", keys1=" + keys1 + ']';
                assert !cache.isLocalLocked(key, true);
            }
            l2.countDown();
            l3.await();
            for (Integer key : keys2) {
                assert !cache.isLocalLocked(key, false);
                assert !cache.isLocalLocked(key, true);
            }
            return null;
        }
    }, "lock-timeout-2");
    t1.start();
    t2.start();
    t1.join();
    t2.join();
    t1.checkError();
    t2.checkError();
    for (Integer key : keys1) {
        assert !cache.isLocalLocked(key, false);
        assert !cache.isLocalLocked(key, true);
    }
    for (Integer key : keys2) {
        assert !cache.isLocalLocked(key, false);
        assert !cache.isLocalLocked(key, true);
    }
}

