        cache.putAll(map);
        tx.commit();
    }
    try (Transaction tx = srv0.transactions().txStart(PESSIMISTIC, REPEATABLE_READ)) {
        for (int i = 0; i < DFLT_PARTITION_COUNT * 3; i++) map.put(i, i + 2);
