/**
 * Note: Test assumes that PDS size didn't change between the first checkpoint and after several node stops.
 * It's not true anymore with free-list caching since the only final free-list state is persisted on checkpoint.
 * Some changed, but currently empty buckets are not persisted and PDS size is smaller after the first checkpoint.
 * Test makes sense only with disabled caching.
 *
 * @throws Exception if fail.
 */
@Test
@WithSystemProperty(key = IgniteSystemProperties.IGNITE_PAGES_LIST_DISABLE_ONHEAP_CACHING, value = "true")
public void testRestoreFreeListCorrectlyAfterRandomStop() throws Exception {
    IgniteEx ignite0 = startGrid(0);
    ignite0.cluster().active(true);
    Random random = new Random();
    List<T2<Integer, byte[]>> cachedEntry = new ArrayList<>();
    IgniteCache<Integer, Object> cache = ignite0.cache(CACHE_NAME);
    for (int j = 0; j < CACHE_SIZE; j++) {
        byte[] val = new byte[random.nextInt(SF.apply(3072))];
        cache.put(j, val);
        cachedEntry.add(new T2<>(j, val));
    }
    Collections.shuffle(cachedEntry);
    //Remove half of entries.
    Collection<T2<Integer, byte[]>> entriesToRemove = cachedEntry.stream().limit(cachedEntry.size() / 2).collect(Collectors.toCollection(ConcurrentLinkedQueue::new));
    entriesToRemove.forEach(t2 -> cache.remove(t2.get1()));
    //During removing of entries free list grab a lot of free pages to itself
    //so will do put/remove again for stabilization of free pages.
    entriesToRemove.forEach(t2 -> cache.put(t2.get1(), t2.get2()));
    entriesToRemove.forEach(t2 -> cache.remove(t2.get1()));
    forceCheckpoint();
    Path cacheFolder = Paths.get(U.defaultWorkDirectory(), DFLT_STORE_DIR, ignite0.name().replaceAll("\\.", "_"), CACHE_DIR_PREFIX + CACHE_NAME);
    Optional<Long> totalPartSizeBeforeStop = totalPartitionsSize(cacheFolder);
    CyclicBarrier nodeStartBarrier = new CyclicBarrier(2);
    int approximateIterationCount = SF.applyLB(10, 6);
    //Approximate count of entries to put per one iteration.
    int iterationDataCount = entriesToRemove.size() / approximateIterationCount;
    startAsyncPutThread(entriesToRemove, nodeStartBarrier);
    //Will stop node during put data several times.
    while (true) {
        stopGrid(0, true);
        ignite0 = startGrid(0);
        ignite0.cluster().active(true);
        if (entriesToRemove.isEmpty())
            break;
        //Notify put thread that node successfully started.
        nodeStartBarrier.await();
        nodeStartBarrier.reset();
        int awaitSize = entriesToRemove.size() - iterationDataCount;
        waitForCondition(() -> entriesToRemove.size() < awaitSize || entriesToRemove.size() == 0, 20000);
    }
    forceCheckpoint();
    Optional<Long> totalPartSizeAfterRestore = totalPartitionsSize(cacheFolder);
    //It allow that size after repeated put operations should be not more than on 15%(heuristic value) greater than before operations.
    //In fact, it should not be multiplied in twice every time.
    long correctedRestoreSize = totalPartSizeAfterRestore.get() - (long) (totalPartSizeBeforeStop.get() * 0.15);
    assertTrue("Size after repeated put operations should be not more than on 15% greater. " + "Size before = " + totalPartSizeBeforeStop.get() + ", Size after = " + totalPartSizeAfterRestore.get(), totalPartSizeBeforeStop.get() > correctedRestoreSize);
}

/**
 * Test checks that free-list works and pages cache flushes correctly under the high concurrent load.
 */
@Test
public void testFreeListUnderLoadMultipleCheckpoints() throws Throwable {
    IgniteEx ignite = startGrid(0);
    ignite.cluster().active(true);
    int minValSize = 64;
    int maxValSize = 128;
    int valsCnt = maxValSize - minValSize;
    int keysCnt = 1_000;
    byte[][] vals = new byte[valsCnt][];
    for (int i = 0; i < valsCnt; i++) vals[i] = new byte[minValSize + i];
    IgniteCache<Object, Object> cache = ignite.createCache(new CacheConfiguration<>(DEFAULT_CACHE_NAME).setAffinity(// Maximize contention per partition.
    new RendezvousAffinityFunction().setPartitions(2)).setAtomicityMode(CacheAtomicityMode.ATOMIC));
    AtomicBoolean done = new AtomicBoolean();
    AtomicReference<Throwable> error = new AtomicReference<>();
    GridCacheDatabaseSharedManager db = (GridCacheDatabaseSharedManager) ignite.context().cache().context().database();
    AtomicLong pageListCacheLimitHolder = db.pageListCacheLimitHolder(ignite.context().cache().cache(DEFAULT_CACHE_NAME).context().dataRegion());
    long initPageListCacheLimit = pageListCacheLimitHolder.get();
    // Add listener after cache is started, so this listener will be triggered after listener for cache.
    db.addCheckpointListener(new CheckpointListener() {

        @Override
        public void onMarkCheckpointBegin(Context ctx) throws IgniteCheckedException {
            // Check under checkpoint write lock that page list cache limit is correctly restored.
            // Need to wait for condition here, since checkpointer can store free-list metadata asynchronously.
            if (!waitForCondition(() -> initPageListCacheLimit == pageListCacheLimitHolder.get(), 1_000L)) {
                IgniteCheckedException e = new IgniteCheckedException("Page list cache limit doesn't restored " + "correctly [init=" + initPageListCacheLimit + ", cur=" + pageListCacheLimitHolder.get() + ']');
                error.set(e);
                throw e;
            }
        }

        @Override
        public void onCheckpointBegin(Context ctx) {
            // No-op.
        }

        @Override
        public void beforeCheckpointBegin(Context ctx) {
            // No-op.
        }
    });
    IgniteInternalFuture<Long> fut = GridTestUtils.runMultiThreadedAsync(() -> {
        Random rnd = new Random();
        try {
            while (!done.get()) {
                int key = rnd.nextInt(keysCnt);
                byte[] val = vals[rnd.nextInt(valsCnt)];
                // Put with changed value size - worst case for free list, since row will be removed first and
                // then inserted again.
                cache.put(key, val);
            }
        } catch (Throwable t) {
            error.set(t);
        }
    }, 20, "cache-put");
    for (int i = 0; i < SF.applyLB(10, 2); i++) {
        if (error.get() != null)
            break;
        forceCheckpoint(ignite);
        doSleep(1_000L);
    }
    done.set(true);
    fut.get();
    stopAllGrids();
    if (error.get() != null)
        throw error.get();
}

/**
 * 1. Start the one node.
 * 2. Configure the default cache.
 * 3. Set the checkpoint listeners(for default region and for all regions) to watch the checkpoint.
 * 4. Fill the data and trigger the checkpoint.
 * 5. Expected: Both listeners should be called.
 * 6. Remove the default region from the checkpoint.
 * 7. Fill the data and trigger the checkpoint.
 * 8. Expected: The only listener for all regions should be called.
 * 9. Return default region back to the checkpoint.
 * 10. Fill the data and trigger the checkpoint.
 * 11. Expected: Both listeners should be called.
 *
 * @throws Exception if fail.
 */
@Test
public void testCheckpointListenersInvokedOnlyIfRegionConfigured() throws Exception {
    //given: One started node with default cache.
    IgniteEx ignite0 = startGrid(0);
    ignite0.cluster().active(true);
    IgniteCache<Integer, Object> cache = ignite0.cache(DEFAULT_CACHE_NAME);
    GridCacheDatabaseSharedManager db = (GridCacheDatabaseSharedManager) (ignite0.context().cache().context().database());
    DataRegion defaultRegion = db.checkpointedDataRegions().stream().filter(region -> DFLT_DATA_REG_DEFAULT_NAME.equals(region.config().getName())).findFirst().orElse(null);
    assertNotNull("Expected default data region in checkpoint list is not found.", defaultRegion);
    //and: Configure the listeners(for default region and for all regions) for watching for checkpoint.
    AtomicInteger checkpointListenerDefaultRegionCounter = checkpointListenerWatcher(db, defaultRegion);
    AtomicInteger checkpointListenerAllRegionCounter = checkpointListenerWatcher(db, null);
    //when: Checkpoint happened.
    fillDataAndCheckpoint(ignite0, cache);
    //then: Both listeners should be called.
    assertEquals(CALLS_COUNT_PER_CHECKPOINT, checkpointListenerDefaultRegionCounter.get());
    assertEquals(CALLS_COUNT_PER_CHECKPOINT, checkpointListenerAllRegionCounter.get());
    //Remove the default region from checkpoint.
    db.checkpointedDataRegions().remove(defaultRegion);
    //when: Checkpoint happened.
    fillDataAndCheckpoint(ignite0, cache);
    //then: Only listener for all regions should be called.
    assertEquals(CALLS_COUNT_PER_CHECKPOINT, checkpointListenerDefaultRegionCounter.get());
    assertEquals(2 * CALLS_COUNT_PER_CHECKPOINT, checkpointListenerAllRegionCounter.get());
    assertTrue("Expected default data region in all regions list is not found.", db.dataRegions().stream().anyMatch(region -> DFLT_DATA_REG_DEFAULT_NAME.equals(region.config().getName())));
    //Return default region back to the checkpoint.
    db.checkpointedDataRegions().add(defaultRegion);
    //when: Checkpoint happened.
    fillDataAndCheckpoint(ignite0, cache);
    //then: Both listeners should be called.
    assertEquals(2 * CALLS_COUNT_PER_CHECKPOINT, checkpointListenerDefaultRegionCounter.get());
    assertEquals(3 * CALLS_COUNT_PER_CHECKPOINT, checkpointListenerAllRegionCounter.get());
}

