/**
 * If joining node has incompatible BinaryMetadata (e.g. when user manually copies binary_meta file),
 * coordinator detects it and fails the node providing information about conflict.
 *
 * @see <a href="https://issues.apache.org/jira/browse/IGNITE-7258">IGNITE-7258</a>
 * refer to the following JIRA for more context about the problem verified by the test.
 */
@Test
public void testNodeWithIncompatibleMetadataIsProhibitedToJoinTheCluster() throws Exception {
    final String decimalFieldName = "decField";
    Ignite igniteA = startGridInASeparateWorkDir("A");
    Ignite igniteB = startGridInASeparateWorkDir("B");
    String bConsId = igniteB.cluster().localNode().consistentId().toString();
    igniteA.active(true);
    IgniteCache<Object, Object> cache = igniteA.cache(CACHE_NAME);
    BinaryObject bObj = igniteA.binary().builder(DYNAMIC_TYPE_NAME).setField(decimalFieldName, 10).build();
    cache.put(0, bObj);
    int createdTypeId = igniteA.binary().type(DYNAMIC_TYPE_NAME).typeId();
    stopAllGrids();
    Ignite igniteC = startGridInASeparateWorkDir("C");
    String cConsId = igniteC.cluster().localNode().consistentId().toString();
    igniteC.active(true);
    cache = igniteC.cache(CACHE_NAME);
    bObj = igniteC.binary().builder(DYNAMIC_TYPE_NAME).setField(decimalFieldName, 10L).build();
    cache.put(0, bObj);
    stopAllGrids();
    copyIncompatibleBinaryMetadata(String.format(CUSTOM_WORK_DIR_NAME_PATTERN, "C"), cConsId, String.format(CUSTOM_WORK_DIR_NAME_PATTERN, "B"), bConsId, BinaryUtils.binaryMetaFileName(DYNAMIC_TYPE_NAME.toLowerCase().hashCode()));
    startGridInASeparateWorkDir("A");
    String expectedMsg = String.format("Type '%s' with typeId %d has a different/incorrect type for field '%s'. Expected 'int' but 'long' was " + "provided. The type of an existing field can not be changed. Use a different field name or follow " + "this procedure to reuse the current name:\n" + "- Delete data records that use the old field type;\n" + "- Remove metadata by the command: 'control.sh --meta remove --typeId %d'.", DYNAMIC_TYPE_NAME, createdTypeId, decimalFieldName, createdTypeId);
    Throwable thrown = GridTestUtils.assertThrows(log, () -> startGridInASeparateWorkDir("B"), Exception.class, null);
    assertNotNull(thrown.getCause());
    assertNotNull(thrown.getCause().getCause());
    String actualMsg = thrown.getCause().getCause().getMessage();
    assertTrue("Cause is not correct [expected='" + expectedMsg + "', actual='" + actualMsg + "'].", actualMsg.contains(expectedMsg));
}

