                        if (putRate10secs.value() == 0) {
                            zeroDropdown.set(true);
                            run.set(false);
                        }
                        Thread.sleep(1000);
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                } finally {
                    run.set(false);
                }
            }
