                    if (!run.get())
                        break;
                    cache.put(ThreadLocalRandom.current().nextInt(keyCnt), new TestValue(ThreadLocalRandom.current().nextInt(), ThreadLocalRandom.current().nextInt()));
                    putRate10secs.increment();
                    putRate1sec.increment();
                }
