@Test
public void testMetastorageUpdateOnSnapshotFail() throws Exception {
    AtomicInteger keyCnt = new AtomicInteger();
    AtomicBoolean stop = new AtomicBoolean();
    Set<String> writtenKeys = new ConcurrentSkipListSet<>();
    IgniteEx ignite = startGridsWithCache(2, dfltCacheCfg, CACHE_KEYS_RANGE);
    IgniteInternalFuture<?> updFut = GridTestUtils.runMultiThreadedAsync(() -> {
        while (!Thread.currentThread().isInterrupted() && !stop.get()) {
            try {
                String key = SNAPSHOT_PREFIX + keyCnt.getAndIncrement();
                ignite.context().distributedMetastorage().write(key, "value");
                writtenKeys.add(key);
            } catch (IgniteCheckedException e) {
                throw new IgniteException(e);
            }
        }
    }, 3, "dms-updater");
    ((GridCacheDatabaseSharedManager) ignite.context().cache().context().database()).addCheckpointListener(new CheckpointListener() {

        @Override
        public void onMarkCheckpointBegin(Context ctx) {
            if (ctx.progress().reason().contains(SNAPSHOT_NAME)) {
                Map<String, SnapshotFutureTask> locMap = GridTestUtils.getFieldValue(snp(ignite), IgniteSnapshotManager.class, "locSnpTasks");
                // Fail the snapshot task with an exception, all metastorage keys must be successfully continued.
                locMap.get(SNAPSHOT_NAME).acceptException(new IgniteCheckedException("Test exception"));
            }
        }

        @Override
        public void onCheckpointBegin(Context ctx) {
        }

        @Override
        public void beforeCheckpointBegin(Context ctx) {
        }
    });
    IgniteFuture<?> fut = ignite.snapshot().createSnapshot(SNAPSHOT_NAME);
    GridTestUtils.assertThrowsAnyCause(log, fut::get, IgniteCheckedException.class, "Test exception");
    stop.set(true);
    // Load future must complete without exceptions, all metastorage keys must be written.
    updFut.get();
    Set<String> readedKeys = new TreeSet<>();
    ignite.context().distributedMetastorage().iterate(SNAPSHOT_PREFIX, (key, val) -> readedKeys.add(key));
    assertEquals("Not all metastorage keys have been written", writtenKeys, readedKeys);
}

/**
 * Checks, compares CRCs of partitions in snapshot data files against the source.
 * <p>
 * <b>NOTE:</b>
 * This test is actual only for not-encrypted snapshots.
 * Writing the deltas causes several page writes into file. Every page write calls encrypt(). Every repeatable
 * encrypt() produces different record. Even for same original data. Re-writing pages from delta to partition file
 * in the snapshot issues additional encryption before writing to the snapshot partition file. Thus, page in
 * original partition and in snapshot partition has different encrypted CRC and same decrypted CRC. Different
 * encrypted CRC looks like different data in point of view of third-party observer.
 *
 * @throws Exception If fails.
 */
@Test
public void testSnapshotLocalPartitions() throws Exception {
    IgniteEx ig = startGridsWithCache(1, 4096, key -> new AbstractSnapshotSelfTest.Account(key, key), new CacheConfiguration<>(DEFAULT_CACHE_NAME));
    for (int i = 4096; i < 8192; i++) {
        ig.cache(DEFAULT_CACHE_NAME).put(i, new AbstractSnapshotSelfTest.Account(i, i) {

            @Override
            public String toString() {
                return "_" + super.toString();
            }
        });
    }
    GridCacheSharedContext<?, ?> cctx = ig.context().cache().context();
    IgniteSnapshotManager mgr = snp(ig);
    // Collection of pairs group and appropriate cache partition to be snapshot.
    IgniteInternalFuture<?> snpFut = startLocalSnapshotTask(cctx, SNAPSHOT_NAME, F.asMap(CU.cacheId(DEFAULT_CACHE_NAME), null), false, mgr.localSnapshotSenderFactory().apply(SNAPSHOT_NAME));
    snpFut.get();
    File cacheWorkDir = ((FilePageStoreManager) ig.context().cache().context().pageStore()).cacheWorkDir(dfltCacheCfg);
    // Checkpoint forces on cluster deactivation (currently only single node in cluster),
    // so we must have the same data in snapshot partitions and those which left
    // after node stop.
    stopGrid(ig.name());
    // Calculate CRCs.
    IgniteConfiguration cfg = ig.context().config();
    PdsFolderSettings settings = ig.context().pdsFolderResolver().resolveFolders();
    String nodePath = databaseRelativePath(settings.folderName());
    File binWorkDir = binaryWorkDir(cfg.getWorkDirectory(), settings.folderName());
    File marshWorkDir = mappingFileStoreWorkDir(U.workDirectory(cfg.getWorkDirectory(), cfg.getIgniteHome()));
    File snpBinWorkDir = binaryWorkDir(mgr.snapshotLocalDir(SNAPSHOT_NAME).getAbsolutePath(), settings.folderName());
    File snpMarshWorkDir = mappingFileStoreWorkDir(mgr.snapshotLocalDir(SNAPSHOT_NAME).getAbsolutePath());
    final Map<String, Integer> origPartCRCs = calculateCRC32Partitions(cacheWorkDir);
    final Map<String, Integer> snpPartCRCs = calculateCRC32Partitions(FilePageStoreManager.cacheWorkDir(U.resolveWorkDirectory(mgr.snapshotLocalDir(SNAPSHOT_NAME).getAbsolutePath(), nodePath, false), cacheDirName(dfltCacheCfg)));
    assertEquals("Partitions must have the same CRC after file copying and merging partition delta files", origPartCRCs, snpPartCRCs);
    assertEquals("Binary object mappings must be the same for local node and created snapshot", calculateCRC32Partitions(binWorkDir), calculateCRC32Partitions(snpBinWorkDir));
    assertEquals("Marshaller meta mast be the same for local node and created snapshot", calculateCRC32Partitions(marshWorkDir), calculateCRC32Partitions(snpMarshWorkDir));
    File snpWorkDir = mgr.snapshotTmpDir();
    assertEquals("Snapshot working directory must be cleaned after usage", 0, snpWorkDir.listFiles().length);
}

