/**
 * We should handle case when we lost snapshot tag and now it's lower than saved.
 *
 * @throws Exception if failed.
 */
@Test
public void testThatWeDontFailIfSnapshotTagWasLost() throws Exception {
    ByteBuffer buf = createBuffer();
    long basePageId = PageIdUtils.pageId(0, PageIdAllocator.FLAG_IDX, 1);
    assert basePageId >= 0;
    PageIO.setPageId(GridUnsafe.bufferAddress(buf), basePageId);
    int oldTag = 10;
    io.markChanged(buf, basePageId + 1, oldTag, oldTag - 1, PAGE_SIZE);
    for (int i = 1; i < 100; i++) io.markChanged(buf, basePageId + i, oldTag - 1, oldTag - 2, PAGE_SIZE);
    assertTrue(io.isCorrupted(buf));
    for (int i = 1; i < 100; i++) {
        try {
            long id = basePageId + i;
            io.wasChanged(buf, id, oldTag - 1, oldTag - 2, PAGE_SIZE);
            fail();
        } catch (TrackingPageIsCorruptedException ignore) {
            //ignore
        }
    }
    for (int i = 1; i < 100; i++) {
        long id = basePageId + i + 1000;
        io.markChanged(buf, id, oldTag, oldTag - 2, PAGE_SIZE);
    }
    io.resetCorruptFlag(buf);
    assertFalse(io.isCorrupted(buf));
    for (int i = 1; i < 100; i++) {
        long id = basePageId + i + 1000;
        assertTrue(io.wasChanged(buf, id, oldTag, oldTag - 1, PAGE_SIZE));
    }
    for (int i = 1; i < 100; i++) {
        long id = basePageId + i;
        assertFalse(io.wasChanged(buf, id, oldTag, oldTag - 1, PAGE_SIZE));
    }
}

/**
 * Checking to avoid deadlock SegmentArchivedStorage.markAsMovedToArchive -> SegmentLockStorage.locked <->
 * SegmentLockStorage.releaseWorkSegment -> SegmentArchivedStorage.onSegmentUnlocked
 *
 * @throws IgniteCheckedException if failed.
 */
@Test
public void testAvoidDeadlockArchiverAndLockStorage() throws IgniteCheckedException {
    SegmentAware aware = segmentAware(10);
    int iterationCnt = 100_000;
    int segmentToHandle = 1;
    IgniteInternalFuture archiverThread = runAsync(() -> {
        int i = iterationCnt;
        while (i-- > 0) {
            try {
                aware.markAsMovedToArchive(segmentToHandle);
            } catch (IgniteInterruptedCheckedException e) {
                throw new RuntimeException(e);
            }
        }
    });
    IgniteInternalFuture lockerThread = runAsync(() -> {
        int i = iterationCnt;
        while (i-- > 0) {
            if (aware.lock(segmentToHandle))
                aware.unlock(segmentToHandle);
        }
    });
    archiverThread.get();
    lockerThread.get();
}

