    aware.resetWalArchiveSizes();
    fut = awaitThread(() -> aware.awaitExceedMaxArchiveSize(10));
    aware.addSize(1, 4);
    assertFutureIsNotFinish(fut);
    aware.addSize(1, 4);
    assertFutureIsNotFinish(fut);
    aware.addSize(1, 4);
    fut.get(20);
    aware.resetWalArchiveSizes();
    fut = awaitThread(() -> aware.awaitExceedMaxArchiveSize(10));
    aware.interrupt();
    assertTrue(fut.get(20) instanceof IgniteInterruptedCheckedException);
    aware.reset();
    fut = awaitThread(() -> aware.awaitExceedMaxArchiveSize(10));
