/**
 * Test scan query when partitions are concurrently evicting.
 */
@Test
public void testScanQueryOnEvictedPartition() throws Exception {
    cleanPersistenceDir();
    DataStorageConfiguration dsCfg = new DataStorageConfiguration().setDefaultDataRegionConfiguration(new DataRegionConfiguration().setPersistenceEnabled(true));
    IgniteEx grid0 = startGrid(getConfiguration("grid0").setDataStorageConfiguration(dsCfg));
    grid0.cluster().state(ClusterState.ACTIVE);
    IgniteCache<Integer, Integer> cache1 = grid0.getOrCreateCache(new CacheConfiguration<Integer, Integer>("cache1").setAffinity(new RoundRobinAffinityFunction(2)));
    IgniteCache<Integer, Integer> cache2 = grid0.getOrCreateCache(new CacheConfiguration<Integer, Integer>("cache2").setAffinity(new RoundRobinAffinityFunction(2)));
    // Put to partition 0.
    cache1.put(0, 0);
    // Put to partition 1.
    cache1.put(1, 1);
    // Put to partition 0.
    cache2.put(0, 0);
    for (int i = 1; i < 1_000; i += 2) // Put to partition 1.
    cache2.put(i, i);
    Iterator iter1 = cache1.query(new ScanQuery<>().setPageSize(1)).iterator();
    Iterator iter2 = cache1.query(new ScanQuery<>().setPageSize(1)).iterator();
    // Iter 1 check case, when cursor is switched to evicted partition.
    iter1.next();
    // Iter 2 check case, when cursor already moving by partition and this partition is evicted.
    iter2.next();
    iter2.next();
    startGrid(getConfiguration("grid1").setDataStorageConfiguration(dsCfg));
    grid0.cluster().setBaselineTopology(grid0.cluster().topologyVersion());
    // Wait for rebalance and evition of partition 1 to grid 1 for each cache.
    awaitPartitionMapExchange();
    assertTrue(GridTestUtils.waitForCondition(() -> grid0.cachex("cache1").context().topology().localPartition(1).state() == EVICTED && grid0.cachex("cache2").context().topology().localPartition(1).state() == EVICTED, 1_000L));
    // Force checkpoint to destroy evicted partitions store.
    forceCheckpoint(grid0);
    assertFalse(iter1.hasNext());
    GridTestUtils.assertThrowsAnyCause(log, () -> {
        while (iter2.hasNext()) iter2.next();
        return null;
    }, IgniteException.class, "Failed to get next data row");
}

