@Test
public void testDeadlockCacheObjectContext() throws Exception {
    IgniteCache<Integer, Integer> cache0 = null;
    IgniteCache<Integer, Integer> cache1 = null;
    try {
        cache0 = getCache(ignite(0), "cache0");
        cache1 = getCache(ignite(0), "cache1");
        IgniteCache<Integer, Integer> clientCache0 = grid(1).cache("cache0");
        awaitPartitionMapExchange();
        final CyclicBarrier barrier = new CyclicBarrier(2);
        final CountDownLatch latch = new CountDownLatch(1);
        final AtomicInteger threadCnt = new AtomicInteger();
        final AtomicBoolean deadlock = new AtomicBoolean();
        IgniteInternalFuture<Long> fut = GridTestUtils.runMultiThreadedAsync(new Runnable() {

            @Override
            public void run() {
                int threadNum = threadCnt.getAndIncrement();
                Ignite ignite = ignite(0);
                IgniteCache<Integer, Integer> cache1 = ignite.cache("cache" + (threadNum == 0 ? 0 : 1));
                IgniteCache<Integer, Integer> cache2 = ignite.cache("cache" + (threadNum == 0 ? 1 : 0));
                try (Transaction tx = ignite.transactions().txStart(PESSIMISTIC, REPEATABLE_READ, 1000, 0)) {
                    int key1 = threadNum == 0 ? 0 : 1;
                    log.info(">>> Performs put [node=" + ((IgniteKernal) ignite).localNode() + ", tx=" + tx + ", key=" + key1 + ", cache=" + cache1.getName() + ']');
                    cache1.put(key1, 0);
                    barrier.await();
                    int key2 = threadNum == 0 ? 1 : 0;
                    log.info(">>> Performs put [node=" + ((IgniteKernal) ignite).localNode() + ", tx=" + tx + ", key=" + key2 + ", cache=" + cache2.getName() + ']');
                    latch.countDown();
                    cache2.put(key2, 1);
                    tx.commit();
                    log.info(">>> Commit done");
                } catch (Throwable e) {
                    // At least one stack trace should contain TransactionDeadlockException.
                    if (hasCause(e, TransactionTimeoutException.class) && hasCause(e, TransactionDeadlockException.class)) {
                        if (deadlock.compareAndSet(false, true))
                            U.error(log, "At least one stack trace should contain " + TransactionDeadlockException.class.getSimpleName(), e);
                    }
                }
            }
        }, 2, "tx-thread");
        latch.await();
        Ignite client = grid(1);
        try (Transaction tx = client.transactions().txStart(PESSIMISTIC, READ_COMMITTED, 500, 0)) {
            clientCache0.put(0, 3);
            clientCache0.put(1, 3);
            tx.commit();
            log.info(">>> Commit done");
        } catch (CacheException e) {
            assertTrue(X.hasCause(e, TransactionTimeoutException.class));
        } catch (Throwable e) {
            log.error("Unexpected exception occurred", e);
            fail();
        }
        fut.get();
        assertTrue(deadlock.get());
        for (int i = 0; i < NODES_CNT; i++) {
            Ignite ignite = ignite(i);
            IgniteTxManager txMgr = ((IgniteKernal) ignite).context().cache().context().tm();
            Collection<IgniteInternalFuture<?>> futs = txMgr.deadlockDetectionFutures();
            assertTrue(futs.isEmpty());
        }
        //assertNotNull(grid(1).context().cache().context().cacheContext(cacheId));
    } finally {
        if (cache0 != null)
            cache0.destroy();
        if (cache1 != null)
            cache1.destroy();
    }
}

/**
 * We removed locks from toString on Entry. The case, a thread X lock entry, after that trying to do a handshake
 * with connecting node. But, handshake fails on the first attempt. Between these events, timeout worked trying to
 * print this entry, but I locked. The thread X can't reconnect, because timeout worker hangs.
 */
@Test
public void testDeadlockOnTimeoutWorkerAndToString() throws Exception {
    // Setup
    TestDependencyResolver nearDepRslvr = new TestDependencyResolver();
    IgniteEx nearNode = startGrid(0, nearDepRslvr);
    TestDependencyResolver incomingDepRslvr = new TestDependencyResolver(this::resolve);
    IgniteEx incomingNode = startGrid(1, incomingDepRslvr);
    GridTimeoutProcessor tp = nearNode.context().timeout();
    ConnectionClientPool pool = nearDepRslvr.getDependency(ConnectionClientPool.class);
    GridCacheEntryEx ex = getEntry(nearNode, DEFAULT_CACHE_NAME, TEST_KEY);
    // Act
    try {
        // Lock entry in current thread
        ex.lockEntry();
        // Print the entry from another thread via timeObject.
        CountDownLatch entryPrinted = new CountDownLatch(1);
        CountDownLatch entryReadyToPrint = new CountDownLatch(1);
        tp.addTimeoutObject(new EntryPrinterTimeoutObject(ex, entryPrinted, entryReadyToPrint));
        entryReadyToPrint.await();
        // Try to do first handshake with hangs, after reconnect handshake should be passed.
        rejectHandshake.set(true);
        pool.forceCloseConnection(incomingNode.localNode().id());
        nearNode.configuration().getCommunicationSpi().sendMessage(incomingNode.localNode(), UUIDCollectionMessage.of(UUID.randomUUID()));
        // Check
        assertTrue(GridTestUtils.waitForCondition(() -> entryPrinted.getCount() == 0, 5_000));
    } finally {
        ex.unlockEntry();
    }
}

