/**
 * Tests that transactions from near node that has left are rolled back on server nodes.
 *
 * @throws Exception If failed.
 */
@Test
public void testRollbackOnNearNodeLeft() throws Exception {
    Ignite client = startClient();
    Integer pk0 = primaryKey(grid(0).cache(CACHE_NAME));
    Integer pk1 = primaryKey(grid(1).cache(CACHE_NAME));
    CountDownLatch locked = new CountDownLatch(1);
    CountDownLatch blocked = new CountDownLatch(1);
    IgniteInternalFuture<Void> fut = runAsync(new Callable<Void>() {

        @Override
        public Void call() {
            try (Transaction tx0 = client.transactions().txStart()) {
                client.cache(CACHE_NAME).put(pk0, 0);
                locked.countDown();
                awaitQuiet(blocked);
                tx0.commit();
            } catch (Exception ignored) {
                // No-op.
            }
            return null;
        }
    });
    IgniteInternalFuture fut2 = runAsync(new Runnable() {

        @Override
        public void run() {
            try (Transaction tx1 = client.transactions().txStart(PESSIMISTIC, REPEATABLE_READ, 1000, 0)) {
                awaitQuiet(locked);
                client.cache(CACHE_NAME).put(pk1, 1);
                spi(client).blockMessages((node, msg) -> msg instanceof GridNearTxFinishRequest);
                spi(grid(0)).blockMessages((node, msg) -> msg instanceof GridNearLockResponse);
                client.cache(CACHE_NAME).put(pk0, 1);
                fail();
            } catch (Exception e) {
                assertTrue(X.hasCause(e, TransactionTimeoutException.class));
            }
        }
    });
    spi(client).waitForBlocked();
    spi(grid(0)).waitForBlocked();
    fut2.get();
    client.close();
    spi(grid(0)).stopBlock();
    blocked.countDown();
    fut.get();
    for (int i = 0; i < GRID_CNT; i++) assertTrue(grid(i).context().cache().context().tm().activeTransactions().isEmpty());
}

/**
 * Tests rollbacks on topology change.
 */
@Test
public void testRollbackOnTopologyChange() throws Exception {
    final AtomicBoolean stop = new AtomicBoolean();
    final long seed = System.currentTimeMillis();
    final Random r = new Random(seed);
    log.info("Using seed: " + seed);
    AtomicIntegerArray reservedIdx = new AtomicIntegerArray(TOTAL_CNT);
    final int keysCnt = SRV_CNT - 1;
    for (int k = 0; k < keysCnt; k++) grid(0).cache(CACHE_NAME).put(k, (long) 0);
    final CyclicBarrier b = new CyclicBarrier(keysCnt);
    AtomicInteger idGen = new AtomicInteger();
    final IgniteInternalFuture<?> txFut = multithreadedAsync(new Runnable() {

        @Override
        public void run() {
            int key = idGen.getAndIncrement();
            List<Integer> keys = new ArrayList<>();
            for (int k = 0; k < keysCnt; k++) keys.add(k);
            int cntr = 0;
            for (int i = 0; i < ITERATIONS; i++) {
                cntr++;
                int nodeId;
                while (!reservedIdx.compareAndSet((nodeId = r.nextInt(TOTAL_CNT)), 0, 1)) doSleep(10);
                U.awaitQuiet(b);
                final IgniteEx grid = grid(nodeId);
                try (final Transaction tx = grid.transactions().txStart(PESSIMISTIC, REPEATABLE_READ, 0, 0)) {
                    reservedIdx.set(nodeId, 0);
                    // Construct deadlock
                    grid.cache(CACHE_NAME).get(keys.get(key));
                    // Should block.
                    grid.cache(CACHE_NAME).get(keys.get((key + 1) % keysCnt));
                    fail("Deadlock expected");
                } catch (Throwable ignore) {
                    // Expected.
                }
                if (key == 0)
                    log.info("Rolled back: " + cntr);
            }
        }
    }, keysCnt, "tx-lock-thread");
    final IgniteInternalFuture<?> restartFut = multithreadedAsync(new Callable<Void>() {

        @Override
        public Void call() throws Exception {
            while (!stop.get()) {
                final int nodeId = r.nextInt(TOTAL_CNT);
                if (!reservedIdx.compareAndSet(nodeId, 0, 1)) {
                    yield();
                    continue;
                }
                stopGrid(nodeId);
                doSleep(500 + r.nextInt(1000));
                if (nodeId >= SRV_CNT)
                    startClientGrid(nodeId);
                else
                    startGrid(nodeId);
                reservedIdx.set(nodeId, 0);
            }
            return null;
        }
    }, 1, "tx-restart-thread");
    // Wait for iterations to complete.
    txFut.get();
    stop.set(true);
    restartFut.get();
    checkFutures();
}

