        cache2.put(i, i);
    }
    srv.cluster().disableWal(CACHE_NAME_2);
    assertForAllNodes(CACHE_NAME, false);
    assertForAllNodes(CACHE_NAME_2, false);
    for (int i = 20; i < 30; i++) {
