    assertEquals(cache2.size(), 30);
    srv.cluster().enableWal(CACHE_NAME);
    assertForAllNodes(CACHE_NAME, true);
    assertForAllNodes(CACHE_NAME_2, false);
    assertEquals(cache1.size(), 30);
    assertEquals(cache2.size(), 30);
