    try {
        for (int i = 1; i <= 10; i++) {
            Thread.sleep(ThreadLocalRandom.current().nextLong(200, 1000));
            IgniteClientReconnectAbstractTest.reconnectClientNode(log, cli, srv, new Runnable() {

                @Override
                public void run() {
                    // No-op.
                }
            });
            log.info(">>> Finished iteration: " + i);
        }
    } finally {
        done.set(true);
    }
    fut.get();
}

