/**
 * Tests service metrics migrates correclty with the service redeployment.
 */
@Test
public void testRedeploy() throws Exception {
    List<IgniteEx> grids = startGrids(3, false);
    // 2 services per node.
    grid(0).services().deploy(serviceCfg(MyServiceFactory.create(), 1, 0));
    awaitPartitionMapExchange();
    // Only same method metric count must persist across the cluster for the singleton.
    int expectedCnt = Arrays.stream(MyService.class.getDeclaredMethods()).map(Method::getName).collect(Collectors.toSet()).size();
    // Only same method metric count must persist across the cluster for the singleton.
    assertEquals("Only one metric registry can persist for one service instance", expectedCnt, grids.stream().map(GridServiceMetricsTest::metricsCnt).mapToInt(Integer::intValue).sum());
    for (int i = 0; i < grids.size(); ++i) {
        if (metricsCnt(grid(i)) > 0) {
            stopGrid(i);
            awaitPartitionMapExchange();
            break;
        }
    }
    // Only same method metric count must persist across the cluster for the singleton.
    assertEquals("Only one metric registry can persist for one service instance", expectedCnt, G.allGrids().stream().map(grid -> metricsCnt((IgniteEx) grid)).mapToInt(Integer::intValue).sum());
}

