@Test
public void testCountDownCallback() throws InterruptedException {
    AtomicInteger cntr = new AtomicInteger(0);
    AtomicInteger performedCntr = new AtomicInteger(0);
    AtomicBoolean res = new AtomicBoolean();
    int countsTillCb = 30;
    GridCountDownCallback cb = new GridCountDownCallback(countsTillCb, () -> res.set(cntr.get() == countsTillCb && performedCntr.get() == countsTillCb / 5), 0);
    ExecutorService es = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    for (int i = 1; i < 100; i++) {
        es.submit(() -> {
            synchronized (es) {
                int fi = cntr.incrementAndGet();
                if (fi % 5 == 0)
                    performedCntr.incrementAndGet();
                cb.countDown(fi % 5 == 0);
            }
        });
    }
    es.shutdown();
    es.awaitTermination(Long.MAX_VALUE, TimeUnit.SECONDS);
    assertTrue(res.get());
}

