    assertArrayEquals(new int[] { 1, 2, 4, 5 }, U.unique(new int[] { 1, 2, 3, 8 }, 2, new int[] { 2, 4, 5, 6 }, 3));
    assertArrayEquals(new int[] { 1, 2 }, U.unique(new int[] { 1, 2, 3, 8 }, 2, new int[] { 2, 4, 5, 6 }, 0));
}

