                throw ex;
            }
            assertTrue(map.contains(p, hash(key), key.getBytes()));
            assertNotNull(map.get(p, hash(key), key.getBytes()));
            assertEquals(new String(map.get(p, hash(key), key.getBytes())), val);
            assertEquals(++cnt, map.size());
        }
    }
}

