    final AtomicInteger okCnt = new AtomicInteger();
    final CyclicBarrier finishBarrier = new CyclicBarrier(THREADS_CNT, new Runnable() {

        private int i;

        @Override
        public void run() {
            if (++i % 250 == 0)
                X.println("Finished iteration [threadName=" + Thread.currentThread().getName() + ", iter=" + i + ']');
        }
    });
