    srvNodeIds.clear();
    srvIdx.set(0);
    Thread.sleep(3000);
    log.info("Restart server.");
    startServerNodes(1);
    assertTrue(reconnectLatch.await(awaitTime(), MILLISECONDS));
    clientNodeIds.clear();
    clientNodeIds.add(client.cluster().localNode().id());
    checkNodes(1, 1);
    assertFalse(err.get());
}

