        ClusterNode node = grid0.cluster().forServers().nodes().stream().filter(n -> n.id() != grid0.localNode().id()).findFirst().get();
        assertNotNull(node);
        final CountDownLatch cnt = new CountDownLatch(1);
        Ignite segmentedNode = G.allGrids().stream().filter(id -> id.cluster().localNode().id().equals(node.id())).findAny().get();
        assertNotNull(segmentedNode);
        segmentedNode.events().localListen(new IgnitePredicate<Event>() {

            @Override
            public boolean apply(Event evt) {
                cnt.countDown();
                return false;
            }
        }, EVT_NODE_SEGMENTED);
        bean.excludeNode(node.id().toString());
        assertTrue(GridTestUtils.waitForCondition(() -> grid0.cluster().forServers().nodes().size() == srvCnt - 1, 5_000));
        assertTrue("Next node have to be failed within failureDetectionTimeout", cnt.await(grid0.configuration().getFailureDetectionTimeout() + 3000, MILLISECONDS));
        bean.excludeNode(grid0.localNode().id().toString());
    } finally {
        stopAllGrids();
    }
}

