    clientMode = true;
    try {
        for (int i = 0; i < clientsNum; i++) clients.add(startGrid("client" + i));
        Map<Integer, Integer> expMap = new HashMap<>();
        for (int i = 0; i < keysNum; i++) {
            int clientId = keysNum % clientsNum;
