/**
 * Test indexes system view.
 *
 * @throws Exception in case of failure.
 */
@Test
public void testIndexesView() throws Exception {
    IgniteEx srv = startGrid(getConfiguration());
    IgniteEx client = startClientGrid(getConfiguration().setIgniteInstanceName("CLIENT"));
    execSql("CREATE TABLE PUBLIC.AFF_CACHE (ID1 INT, ID2 INT, GEOM GEOMETRY, PRIMARY KEY (ID1))");
    execSql("CREATE SPATIAL INDEX IDX_GEO_1 ON PUBLIC.AFF_CACHE(GEOM)");
    String idxSql = "SELECT " + " CACHE_ID," + " CACHE_NAME," + " SCHEMA_NAME," + " TABLE_NAME," + " INDEX_NAME," + " INDEX_TYPE," + " COLUMNS," + " IS_PK," + " IS_UNIQUE," + " INLINE_SIZE" + " FROM SYS.INDEXES ORDER BY TABLE_NAME, INDEX_NAME";
    List<List<?>> srvNodeIndexes = execSql(srv, idxSql);
    List<List<?>> clientNodeNodeIndexes = execSql(client, idxSql);
    for (List<?> idx : clientNodeNodeIndexes) assertTrue(srvNodeIndexes.contains(idx));
    Object[][] expectedResults = { { -825022849, "SQL_PUBLIC_AFF_CACHE", "PUBLIC", "AFF_CACHE", "IDX_GEO_1", "SPATIAL", "\"GEOM\" ASC", false, false, null }, { -825022849, "SQL_PUBLIC_AFF_CACHE", "PUBLIC", "AFF_CACHE", "__SCAN_", "SCAN", null, false, false, null }, { -825022849, "SQL_PUBLIC_AFF_CACHE", "PUBLIC", "AFF_CACHE", "_key_PK", "BTREE", "\"ID1\" ASC", true, true, 5 }, { -825022849, "SQL_PUBLIC_AFF_CACHE", "PUBLIC", "AFF_CACHE", "_key_PK_hash", "HASH", "\"ID1\" ASC", false, true, null } };
    for (int i = 0; i < srvNodeIndexes.size(); i++) {
        List<?> resRow = srvNodeIndexes.get(i);
        Object[] expRow = expectedResults[i];
        assertEquals(expRow.length, resRow.size());
        for (int j = 0; j < expRow.length; j++) assertEquals(expRow[j], resRow.get(j));
    }
}

