/**
 */
@Test
public void testRangeWithNulls() {
    Function<Integer, Person> persGen = i -> {
        Integer val = i < CNT / 10 ? null : i;
        return person("intNullId", val);
    };
    insertData(i -> i, persGen, CNT);
    int pivot = CNT / 5;
    String intNullIdx = idxName("intNullId");
    // Should include all.
    IndexQuery<Long, Person> qry = new IndexQuery<>(Person.class, intNullIdx);
    check(cache.query(qry), 0, CNT, i -> i, persGen);
    // Should include nulls.
    qry = new IndexQuery<Long, Person>(Person.class, intNullIdx).setCriteria(lt("intNullId", pivot));
    check(cache.query(qry), 0, CNT / 5, i -> i, persGen);
    // Should exclude nulls.
    qry = new IndexQuery<Long, Person>(Person.class, intNullIdx).setCriteria(gte("intNullId", 0));
    check(cache.query(qry), CNT / 10, CNT, i -> i, persGen);
    // Should return only nulls.
    qry = new IndexQuery<Long, Person>(Person.class, intNullIdx).setCriteria(lt("intNullId", 0));
    check(cache.query(qry), 0, CNT / 10, i -> i, persGen);
    // Should return only nulls.
    qry = new IndexQuery<Long, Person>(Person.class, intNullIdx).setCriteria(lte("intNullId", null));
    check(cache.query(qry), 0, CNT / 10, i -> i, persGen);
    // Should return all non nulls.
    qry = new IndexQuery<Long, Person>(Person.class, intNullIdx).setCriteria(gt("intNullId", null));
    check(cache.query(qry), CNT / 10, CNT, i -> i, persGen);
    // Should return all items.
    qry = new IndexQuery<Long, Person>(Person.class, intNullIdx).setCriteria(gte("intNullId", null));
    check(cache.query(qry), 0, CNT, i -> i, persGen);
}

