    IndexQuery<Long, Person> qry = new IndexQuery<Long, Person>(Person.class, qryIdx).setCriteria(between("id", CNT / 2, CNT + CNT / 2));
    Iterator<Cache.Entry<Long, Person>> cursor = cache.query(qry).iterator();
    for (int i = 0; i < CNT / 10; i++) cursor.next();
    insertData(CNT, CNT * 2);
    int size = CNT / 10;
    while (cursor.hasNext()) {
        cursor.next();
        size++;
    }
    assertEquals(CNT + 1, size);
}

