@Test
public void testRangeQueries() throws Exception {
    // Query empty cache.
    IndexQuery<Long, Person> qry = new IndexQuery<>(Person.class, idxName);
    assertTrue(cache.query(qry).getAll().isEmpty());
    // Add data
    insertData();
    qry = new IndexQuery<>(Person.class, idxName);
    check(qry, 0, CNT);
    // Range queries.
    String fld = idxName.equals(IDX) ? "id" : "descId";
    int pivot = new Random().nextInt(CNT);
    // Eq.
    qry = new IndexQuery<Long, Person>(Person.class, idxName).setCriteria(eq(fld, pivot));
    check(qry, pivot, pivot + 1);
    // Lt.
    qry = new IndexQuery<Long, Person>(Person.class, idxName).setCriteria(lt(fld, pivot));
    check(qry, 0, pivot);
    // Lte.
    qry = new IndexQuery<Long, Person>(Person.class, idxName).setCriteria(lte(fld, pivot));
    check(qry, 0, pivot + 1);
    // Gt.
    qry = new IndexQuery<Long, Person>(Person.class, idxName).setCriteria(gt(fld, pivot));
    check(qry, pivot + 1, CNT);
    // Gte.
    qry = new IndexQuery<Long, Person>(Person.class, idxName).setCriteria(gte(fld, pivot));
    check(qry, pivot, CNT);
    // Between.
    int lower = new Random().nextInt(CNT / 2);
    int upper = lower + CNT / 20;
    qry = new IndexQuery<Long, Person>(Person.class, idxName).setCriteria(between(fld, lower, upper));
    check(qry, lower, upper + 1);
}

