/**
 * @throws Exception If failed.
 */
@Test
public void testRestarts() throws Exception {
    int duration = 90 * 1000;
    int qryThreadNum = 5;
    // 2 of 4 data nodes
    int restartThreadsNum = 2;
    final int nodeLifeTime = 2 * 1000;
    final int logFreq = 10;
    startGridsMultiThreaded(GRID_CNT);
    // The last is client only.
    final AtomicIntegerArray locks = new AtomicIntegerArray(GRID_CNT - 1);
    fillCaches();
    final List<List<?>> pRes = grid(0).cache("pu").query(new SqlFieldsQuery(QRY)).getAll();
    Thread.sleep(3000);
    assertEquals(pRes, grid(0).cache("pu").query(new SqlFieldsQuery(QRY)).getAll());
    assertFalse(pRes.isEmpty());
    final AtomicInteger qryCnt = new AtomicInteger();
    final AtomicBoolean qrysDone = new AtomicBoolean();
    final List<Integer> cacheSize = new ArrayList<>(4);
    for (int i = 0; i < GRID_CNT - 1; i++) {
        int j = 0;
        for (String cacheName : F.asList("co", "pr", "pe", "pu")) {
            IgniteCache<?, ?> cache = grid(i).cache(cacheName);
            assertClient(cache, false);
            if (i == 0)
                cacheSize.add(cache.size());
            else
                assertEquals(cacheSize.get(j++).intValue(), cache.size());
        }
    }
    int j = 0;
    for (String cacheName : F.asList("co", "pr", "pe", "pu")) {
        IgniteCache<?, ?> cache = grid(GRID_CNT - 1).cache(cacheName);
        assertClient(cache, true);
        assertEquals(cacheSize.get(j++).intValue(), cache.size());
    }
    final IgniteCache<?, ?> clientCache = grid(GRID_CNT - 1).cache("pu");
    IgniteInternalFuture<?> fut1 = multithreadedAsync(new CAX() {

        @Override
        public void applyx() throws IgniteCheckedException {
            GridRandom rnd = new GridRandom();
            while (!qrysDone.get()) {
                SqlFieldsQuery qry = new SqlFieldsQuery(QRY);
                boolean smallPageSize = rnd.nextBoolean();
                if (smallPageSize)
                    qry.setPageSize(3);
                List<List<?>> res;
                try {
                    res = clientCache.query(qry).getAll();
                } catch (CacheException e) {
                    assertTrue("On large page size must retry.", smallPageSize);
                    boolean failedOnRemoteFetch = false;
                    for (Throwable th = e; th != null; th = th.getCause()) {
                        if (!(th instanceof CacheException))
                            continue;
                        if (th.getMessage() != null && th.getMessage().startsWith("Failed to fetch data from node:")) {
                            failedOnRemoteFetch = true;
                            break;
                        }
                    }
                    if (!failedOnRemoteFetch) {
                        e.printStackTrace();
                        fail("Must fail inside of GridResultPage.fetchNextPage or subclass.");
                    }
                    res = FAKE;
                }
                if (res != FAKE && !res.equals(pRes)) {
                    int j = 0;
                    // Check for data loss.
                    for (String cacheName : F.asList("co", "pr", "pe", "pu")) {
                        assertEquals(cacheName, cacheSize.get(j++).intValue(), grid(GRID_CNT - 1).cache(cacheName).size());
                    }
                    // Fail with nice message.
                    assertEquals(pRes, res);
                }
                int c = qryCnt.incrementAndGet();
                if (c % logFreq == 0)
                    info("Executed queries: " + c);
            }
        }
    }, qryThreadNum, "query-thread");
    final AtomicInteger restartCnt = new AtomicInteger();
    final AtomicBoolean restartsDone = new AtomicBoolean();
    IgniteInternalFuture<?> fut2 = multithreadedAsync(new Callable<Object>() {

        @SuppressWarnings({ "BusyWait" })
        @Override
        public Object call() throws Exception {
            GridRandom rnd = new GridRandom();
            while (!restartsDone.get()) {
                int g;
                do {
                    g = rnd.nextInt(locks.length());
                } while (!locks.compareAndSet(g, 0, -1));
                log.info("Stop node: " + g);
                stopGrid(g);
                Thread.sleep(rnd.nextInt(nodeLifeTime));
                log.info("Start node: " + g);
                startGrid(g);
                Thread.sleep(rnd.nextInt(nodeLifeTime));
                locks.set(g, 0);
                int c = restartCnt.incrementAndGet();
                if (c % logFreq == 0)
                    info("Node restarts: " + c);
            }
            return true;
        }
    }, restartThreadsNum, "restart-thread");
    Thread.sleep(duration);
    info("Stopping..");
    restartsDone.set(true);
    fut2.get();
    info("Restarts stopped.");
    qrysDone.set(true);
    fut1.get();
    info("Queries stopped.");
}

/**
 * Tests partition validation.
 */
@Test
public void testPartitions() {
    final SqlFieldsQuery qry = new SqlFieldsQuery("select 1");
    // Empty set is not allowed.
    failIfNotThrown(new Runnable() {

        @Override
        public void run() {
            qry.setPartitions();
        }
    });
    // Duplicates are not allowed.
    failIfNotThrown(new Runnable() {

        @Override
        public void run() {
            qry.setPartitions(0, 1, 2, 1);
        }
    });
    // Values out of range are not allowed.
    failIfNotThrown(new Runnable() {

        @Override
        public void run() {
            qry.setPartitions(-1, 0, 1);
        }
    });
    // Duplicates with unordered input are not allowed.
    failIfNotThrown(new Runnable() {

        @Override
        public void run() {
            qry.setPartitions(3, 2, 2);
        }
    });
    // Values out of range are not allowed.
    failIfNotThrown(new Runnable() {

        @Override
        public void run() {
            qry.setPartitions(-1, 0, 1);
        }
    });
    // Expecting ordered set.
    int[] tmp = new int[] { 6, 2, 3 };
    qry.setPartitions(tmp);
    assertTrue(Arrays.equals(new int[] { 2, 3, 6 }, tmp));
    // If already ordered expecting same instance.
    qry.setPartitions((tmp = new int[] { 0, 1, 2 }));
    assertTrue(tmp == qry.getPartitions());
}

/**
 * Tests join query within region on unstable topology.
 */
@Test
public void testJoinQueryUnstableTopology() throws Exception {
    final AtomicBoolean stop = new AtomicBoolean();
    final AtomicIntegerArray states = new AtomicIntegerArray(GRIDS_COUNT);
    final Ignite client = grid("client");
    final AtomicInteger cnt = new AtomicInteger();
    IgniteInternalFuture<?> fut = multithreadedAsync(new Runnable() {

        @Override
        public void run() {
            while (!stop.get()) {
                doTestJoinQuery(client, rnd.nextInt(PARTS_PER_REGION.length) + 1);
                int cur = cnt.incrementAndGet();
                if (cur % 100 == 0)
                    log().info("Queries count: " + cur);
            }
        }
    }, QUERY_THREADS_CNT);
    final AtomicIntegerArray restartStats = new AtomicIntegerArray(GRIDS_COUNT);
    IgniteInternalFuture<?> fut2 = multithreadedAsync(new Callable<Void>() {

        @Override
        public Void call() throws Exception {
            while (!stop.get()) {
                int grid = rnd.nextInt(GRIDS_COUNT);
                String name = getTestIgniteInstanceName(grid);
                Integer regionId = regionForGrid(name);
                // Restart nodes only from region with enough number of nodes.
                if (regionId != 3 && regionId != 4)
                    continue;
                if (states.compareAndSet(grid, 0, 1)) {
                    restartStats.incrementAndGet(grid);
                    try {
                        stopGrid(grid);
                        Thread.sleep(rnd.nextInt(NODE_RESTART_TIME));
                        IgniteEx g = startGrid(grid);
                        Thread.sleep(rnd.nextInt(NODE_RESTART_TIME));
                        // Avoid data loss on random restarts.
                        assertTrue(GridTestUtils.waitForCondition(new GridAbsPredicate() {

                            @Override
                            public boolean apply() {
                                return !g.cachex("cl").context().topology().hasMovingPartitions() || !g.cachex("de").context().topology().hasMovingPartitions();
                            }
                        }, 30_000));
                    } finally {
                        states.set(grid, 0);
                    }
                }
            }
            return null;
        }
    }, RESTART_THREADS_CNT);
    // Test duration.
    U.sleep(GridTestUtils.SF.applyLB(60_000, 20_000));
    stop.set(true);
    try {
        fut.get();
        fut2.get();
    } finally {
        log().info("Queries count: " + cnt.get());
        for (int i = 0; i < GRIDS_COUNT; i++) log().info("Grid [name = " + getTestIgniteInstanceName(i) + ", idx=" + i + " ] restarts count: " + restartStats.get(i));
    }
}

