    assertNotNull(field);
    assertEquals(personCache.getName(), field.schemaName());
    assertEquals("PERSON", field.typeName());
    assertEquals("AGE", field.fieldName());
    assertEquals(Integer.class.getName(), field.fieldTypeName());
    assert metaIt.hasNext();
