@Test
public void testLargeResult() {
    // Fill cache.
    try (IgniteDataStreamer<Integer, Integer> streamer = ignite(0).dataStreamer(DEFAULT_CACHE_NAME)) {
        streamer.perNodeBufferSize(20000);
        for (// default max merge table size is 10000
        int i = 0; // default max merge table size is 10000
        i < 50_000; // default max merge table size is 10000
        i++) streamer.addData(i, i);
        streamer.flush();
    }
    IgniteCache<Integer, Integer> cache = ignite(0).cache(DEFAULT_CACHE_NAME);
    try (QueryCursor<List<?>> res = cache.query(new SqlFieldsQuery("select _val from Integer where _key between ? and ?").setArgs(10_000, 40_000))) {
        int cnt = 0;
        for (List<?> row : res) {
            cnt++;
            int val = (Integer) row.get(0);
            assertTrue(val >= 10_000 && val <= 40_000);
        }
        // Streaming of a large result works well.
        assertEquals(30_001, cnt);
    }
    // Currently we have no ways to do multiple passes through a merge table.
}

