/**
 * Test that after index creation index is used by queries.
 */
@Test
public void testCreateIndex() throws Exception {
    IgniteCache<KeyClass, ValueClass> cache = cache();
    assertSize(3);
    cache.query(new SqlFieldsQuery("CREATE INDEX \"" + IDX_NAME_1_ESCAPED + "\" ON \"" + TBL_NAME_ESCAPED + "\"(\"" + FIELD_NAME_1_ESCAPED + "\" ASC)")).getAll();
    // Test that local queries on all nodes use new index.
    for (int i = 0; i < 4; i++) {
        if (ignite(i).configuration().isClientMode())
            continue;
        List<List<?>> locRes = ignite(i).cache("cache").query(new SqlFieldsQuery("explain select \"id\" from " + "\"cache\".\"ValueClass\" where \"field1\" = 1").setLocal(true)).getAll();
        assertEquals(F.asList(Collections.singletonList("SELECT\n" + "    \"id\"\n" + "FROM \"cache\".\"ValueClass\"\n" + "    /* \"cache\".\"idx_1\": \"field1\" = 1 */\n" + "WHERE \"field1\" = 1")), locRes);
    }
    assertSize(3);
    cache.remove(new KeyClass(2));
    assertSize(2);
    cache.put(new KeyClass(4), new ValueClass(1L));
    assertSize(3);
}

