                cache.put(childKey, new JoinTestChild(i));
                expCnt++;
            }
        }
        SqlFieldsQuery qry = new SqlFieldsQuery("select c.parentId, p.id from " + "JoinTestChild c join JoinTestParent p on (c.parentId = p.id)").setDistributedJoins(true);
