    for (int i = 0; i < cnt; i++) {
        Abc abc = new Abc(rnd.nextInt(2000), rnd.nextInt(100), rnd.nextInt(5));
        //            X.println(">> " + i + " " + abc);
        cache.put(i, abc);
        add(as, abc.a, true);
        add(bs, abc.b, true);
        add(cs, abc.c, true);
        if (rnd.nextInt(1000) == 0) {
            switch(rnd.nextInt(3)) {
                case 0:
                    check(as, cache, "a");
                    break;
                case 1:
                    check(bs, cache, "b");
                    break;
                case 2:
                    check(cs, cache, "c");
                    break;
                default:
                    fail();
            }
        }
    }
    check(as, cache, "a");
    check(bs, cache, "b");
    check(cs, cache, "c");
