public void testParseAlterTableAddColumn() throws Exception {
    assertAlterTableAddColumnEquals(buildAlterTableAddColumn("SCH2", "Person", false, false, c("COMPANY", Value.STRING)), "ALTER TABLE SCH2.Person ADD company varchar");
    assertAlterTableAddColumnEquals(buildAlterTableAddColumn("SCH2", "Person", true, true, c("COMPANY", Value.STRING)), "ALTER TABLE IF EXISTS SCH2.Person ADD if not exists company varchar");
    assertAlterTableAddColumnEquals(buildAlterTableAddColumn("SCH2", "Person", false, true, c("COMPANY", Value.STRING), c("city", Value.STRING)), "ALTER TABLE IF EXISTS SCH2.Person ADD (company varchar, \"city\" varchar)");
    assertAlterTableAddColumnEquals(buildAlterTableAddColumn("SCH2", "City", false, true, c("POPULATION", Value.INT)), "ALTER TABLE IF EXISTS SCH2.\"City\" ADD (population int)");
    assertAlterTableAddColumnEquals(buildAlterTableAddColumn("SCH2", "City", false, true, cn("POPULATION", Value.INT)), "ALTER TABLE IF EXISTS SCH2.\"City\" ADD (population int NOT NULL)");
    // There's no table with such name, but H2 parsing does not fail just yet.
    assertAlterTableAddColumnEquals(buildAlterTableAddColumn("SCH2", "City", false, false, c("POPULATION", Value.INT)), "ALTER TABLE SCH2.\"City\" ADD (population int)");
    assertAlterTableAddColumnEquals(buildAlterTableAddColumn("SCH2", "Person", true, false, c("NAME", Value.STRING)), "ALTER TABLE SCH2.Person ADD if not exists name varchar");
    // There's a column with such name, but H2 parsing does not fail just yet.
    assertAlterTableAddColumnEquals(buildAlterTableAddColumn("SCH2", "Person", false, false, c("NAME", Value.STRING)), "ALTER TABLE SCH2.Person ADD name varchar");
    // IF NOT EXISTS with multiple columns.
    assertParseThrows("ALTER TABLE IF EXISTS SCH2.Person ADD if not exists (company varchar, city varchar)", DbException.class, null);
    // Both BEFORE keyword.
    assertParseThrows("ALTER TABLE IF EXISTS SCH2.Person ADD if not exists company varchar before addrid", IgniteSQLException.class, "BEFORE keyword is not supported");
    // Both AFTER keyword.
    assertParseThrows("ALTER TABLE IF EXISTS SCH2.Person ADD if not exists company varchar after addrid", IgniteSQLException.class, "AFTER keyword is not supported");
    assertParseThrows("ALTER TABLE IF EXISTS SCH2.Person ADD if not exists company varchar first", IgniteSQLException.class, "FIRST keyword is not supported");
    // No such schema.
    assertParseThrows("ALTER TABLE SCH5.\"Person\" ADD (city varchar)", DbException.class, null);
}

