@Test
public void testUnsupportedAlterTableColumn() {
    execSql("CREATE TABLE test ( " + "id integer PRIMARY KEY, " + "val varchar DEFAULT 'test_val')");
    assertSqlUnsupported("ALTER TABLE test ALTER COLUMN val SELECTIVITY 1");
