/**
 */
@Test
public void testSubqueryTableView() {
    final String cacheName = "a1";
    final String creationQry = "CREATE TABLE t1 ( id INT NOT NULL, int_col1 INT NOT NULL, PRIMARY KEY (id)) " + //, WRAP_VALUE=false
    "WITH \"TEMPLATE=partitioned, cache_name=%s\"";
    try (FieldsQueryCursor<List<?>> cur = initCache.query(new SqlFieldsQuery(String.format(creationQry, cacheName)))) {
        assertNotNull(cur);
        List<List<?>> rows = cur.getAll();
        assertEquals(1, rows.size());
        assertEquals(0L, rows.get(0).get(0));
    }
    final IgniteCache<Integer, Integer> cache = ignite.getOrCreateCache(cacheName);
    try (FieldsQueryCursor<List<?>> cur = cache.query(new SqlFieldsQuery("INSERT INTO t1 (id,int_col1) VALUES (1,0),(2,2),(3,0),(4,2)"))) {
        assertNotNull(cur);
        List<List<?>> rows = cur.getAll();
        assertEquals(1, rows.size());
        assertEquals(4L, rows.get(0).get(0));
    }
    try (FieldsQueryCursor<List<?>> cur = cache.query(new SqlFieldsQuery("SELECT * FROM ( SELECT * FROM t1 WHERE int_col1 > 0 ORDER BY id ) WHERE int_col1 = 1"))) {
        assertNotNull(cur);
        List<List<?>> rows = cur.getAll();
        assertEquals(0, rows.size());
    }
    try (FieldsQueryCursor<List<?>> cur = cache.query(new SqlFieldsQuery("SELECT * FROM ( SELECT * FROM t1 WHERE int_col1 < 0 ORDER BY id ) WHERE int_col1 = 1"))) {
        assertNotNull(cur);
        List<List<?>> rows = cur.getAll();
        assertEquals(0, rows.size());
    }
    try (FieldsQueryCursor<List<?>> cur = cache.query(new SqlFieldsQuery("SELECT * FROM ( SELECT * FROM t1 WHERE int_col1 > 0 ORDER BY id ) WHERE int_col1 = 2"))) {
        assertNotNull(cur);
        List<List<?>> rows = cur.getAll();
        assertEquals(2, rows.size());
        assertEquals(2, rows.get(0).get(0));
        assertEquals(2, rows.get(0).get(1));
        assertEquals(4, rows.get(1).get(0));
        assertEquals(2, rows.get(1).get(1));
    }
}

