@Test
public void testInsertKeyWithNullKeyPartsDefault() {
    sql("CREATE TABLE test (id1 INT, id2 INT DEFAULT 20, val INT, CONSTRAINT PK PRIMARY KEY(id1, id2))");
    sql("insert into test (id1, val) values (0, 1);");
    sql("insert into test (val) values (2);");
    assertThrows(log, () -> sql("insert into test (id1, val) values (0, 1);"), TransactionDuplicateKeyException.class, "Duplicate key during INSERT");
    assertThrows(log, () -> sql("insert into test (val) values (2);"), TransactionDuplicateKeyException.class, "Duplicate key during INSERT");
