    assertEquals(sql.get(0).get(1), 20);
    assertEquals(sql.get(0).get(2), 1);
    assertNull(sql.get(1).get(0));
    assertEquals(sql.get(1).get(1), 20);
    assertEquals(sql.get(1).get(2), 2);
}

