    List<List<Object>> res = c.query(new SqlFieldsQuery("select grp, GROUP_CONCAT(str0) from Value WHERE id < ? group by grp ").setCollocated(true).setArgs(KEY_BASE_FOR_DUPLICATES)).getAll();
