    List<List<Object>> res = c.query(new SqlFieldsQuery("select grp, GROUP_CONCAT(str0 SEPARATOR '.') from Value group by grp")).getAll();
    List<List<Object>> expRes = Arrays.asList(Arrays.asList(1, "A"), Arrays.asList(2, "B.C"), Arrays.asList(3, "D.E.F"), Arrays.asList(4, "G.H.I.J"), Arrays.asList(5, "K.L.M.N.O"), Arrays.asList(6, "P.Q.R.S.T.U"));
    assertEquals(res.size(), expRes.size());
    // Join order is not guaranteed.
    for (int i = 0; i < res.size(); i++) {
        List<Object> row = res.get(i);
        Integer idx = (Integer) row.get(0);
        String s0 = (String) row.get(1);
        String s1 = Stream.of(s0.split("\\.")).sorted().collect(Collectors.joining("."));
        assertEqualsCollections(expRes.get(idx - 1), Arrays.asList(idx, s1));
    }
}

