@Test
public void testPushDownSubquery() {
    IgniteCache<Integer, Person> c = ignite(CLIENT).getOrCreateCache(cacheConfig("ps", true, Integer.class, Person.class));
    try {
        String subqry = "(select max(p.id) as id, p.depId from Person p group by p.depId)";
        // Subquery in where clause.
        String qry = "select 1 from Person p0 join " + subqry + " p1 on p0.id = p1.id where p0.id = " + " (select p.id from Person p where p.id = p0.id)";
        assertEquals(0, c.query(new SqlFieldsQuery(qry)).getAll().size());
        List<List<?>> plan = c.query(new SqlFieldsQuery("explain " + qry)).getAll();
        X.println(" Plan: " + plan);
        assertEquals(3, plan.size());
        String rdc = (String) plan.get(2).get(0);
        assertFalse(rdc.contains("PERSON"));
        qry = "select (select p.id from Person p where p.id = p0.id) from Person p0 join " + subqry + " p1 on p0.id = p1.id";
        assertEquals(0, c.query(new SqlFieldsQuery(qry)).getAll().size());
        plan = c.query(new SqlFieldsQuery("explain " + qry)).getAll();
        X.println(" Plan: " + plan);
        assertEquals(3, plan.size());
        rdc = (String) plan.get(2).get(0);
        assertFalse(rdc.contains("PERSON"));
    } finally {
        c.destroy();
    }
}

