                assertEquals(metrics.getTotalCpus(), resMetrics.get(0).get(30));
                assertEquals(metrics.getCurrentCpuLoad(), resMetrics.get(0).get(31));
                assertEquals(metrics.getAverageCpuLoad(), resMetrics.get(0).get(32));
