    }, IllegalArgumentException.class);
}

/**
 * Check change the default query timeout via API of the {@link DistributedSqlConfiguration} on runtime.
 * Steps:
 * - start two servers an one client node;
 * - set default query timeout to 2000 ms;
 * - execute query that takes 1000 ms;
 * - check that query is successful;
 * - set default query timeout to 500 ms;
 * - execute query that takes 1000 ms;
 * - check that query fails with QueryCancelledException.
 */
@Test
public void testChangeDefaultTimeout() throws Exception {
    startGrids(2);
    startClientGrid(2);
    setDefaultQueryTimeout(2000);
    TimedQueryHelper helper = new TimedQueryHelper(1000, DEFAULT_CACHE_NAME);
    helper.createCache(grid(0));
    String sql = helper.buildTimedQuery();
    // assert no exception
    for (Ignite ign : G.allGrids()) executeQuery(ign, sql);
    setDefaultQueryTimeout(500);
    for (final Ignite ign : G.allGrids()) GridTestUtils.assertThrowsWithCause(() -> executeQuery(ign, sql), QueryCancelledException.class);
}

/**
 * Check cases when JDBC query timeout value (sets in second) more then Integer range in milliseconds.
 * Steps:
 * - start server node;
 * - execute queries with huge timeout in seconds: (timeout_value * 1000 more than Integer.MAX_VALUE);
 * - the query must be executed successful.
 */
@Test
public void testExplicitTimeoutMoreThenMaxValue() throws Exception {
    startGrid(0);
    setDefaultQueryTimeout(500);
    TimedQueryHelper helper = new TimedQueryHelper(1000, DEFAULT_CACHE_NAME);
    helper.createCache(grid(0));
    String sql = helper.buildTimedQuery();
    int[] hugeTimeouts = new int[] { Integer.MAX_VALUE / 1000 + 1, Integer.MAX_VALUE };
    try (Connection conn = DriverManager.getConnection("jdbc:ignite:thin://127.0.0.1")) {
        for (int timeout : hugeTimeouts) {
            try (Statement stmt = conn.createStatement()) {
                stmt.setQueryTimeout(timeout);
                ResultSet rs = stmt.executeQuery(sql);
                int cnt = 0;
                while (rs.next()) cnt++;
                assertTrue(cnt > 0);
            }
        }
    }
}

