@Test
public void joinPrimaryKeyAndAffinityKey() {
    execute(new SqlFieldsQuery("CREATE TABLE A (k1 VARCHAR PRIMARY KEY, v2 VARCHAR);"));
    execute(new SqlFieldsQuery("CREATE TABLE B (k1 VARCHAR, ak2 VARCHAR, v3 VARCHAR, PRIMARY KEY(k1, ak2)) with \"AFFINITY_KEY=ak2\";"));
    // Correct joins.
    checkLogListener(false, "SELECT * FROM A a " + joinType + " B b on a.k1 = b.ak2");
    checkLogListener(false, "SELECT * FROM A a " + joinType + " B b on a.k1 = b.ak2 WHERE b.k1 = ?", "1");
    checkLogListener(false, "SELECT * FROM A a " + joinType + " B b where a.k1 = b.ak2");
    checkLogListener(false, "SELECT * FROM A a " + joinType + " B b where b.ak2 = a.k1");
    checkLogListener(false, "SELECT * FROM A a " + joinType + " B b on a.k1 = b.ak2 WHERE a.k1 < b.ak2");
    // Wrong joins.
    checkLogListener(true, "SELECT * FROM A a " + joinType + " B b on a.k1 = b.k1");
    checkLogListener(true, "SELECT * FROM A a " + joinType + " B b on a.k1 = b.k1 and a.v2 = b.ak2");
    checkLogListener(true, "SELECT * FROM A a " + joinType + " B b on a.k1 > b.ak2");
    checkLogListener(true, "SELECT * FROM A a " + joinType + " B b where a.k1 = ? and b.ak2 = ?", "1", "1");
}

