/**
 * Check distributed INNER JOIN.
 */
@Test
public void testInnerDistributedJoin() {
    Arrays.asList(true, false).forEach(forceOrder -> testAllNodes(node -> {
        final String qryTpl = "SELECT d.id, d.name, a.address " + "FROM Department d INNER JOIN Address a " + "ON d.%s = a.%s";
        Result actIdxOnOn = executeFrom(distributedJoinQry(forceOrder, qryTpl, "id", "depId"), node);
        Result actIdxOffOn = executeFrom(distributedJoinQry(true, qryTpl, "idNoidx", "depId"), node);
        List<List<Object>> exp = doInnerJoin(node.cache(DEP_CACHE_NAME), node.cache(ADDR_CACHE_NAME), (dep, addr) -> sqlEq(dep.get("ID"), addr.get("DEPID")), (dep, addr) -> Arrays.asList(dep.get("ID"), dep.get("NAME"), addr.get("ADDRESS")));
        assertContainsEq("Distributed join on 'idx = idx' returned unexpected result. " + "Preserve join order = " + forceOrder + ".", actIdxOnOn.values(), exp);
        assertContainsEq("Distributed join on 'noidx = idx' returned unexpected result. " + "Preserve join order = " + forceOrder + ".", actIdxOffOn.values(), exp);
    }));
}

