        }, locks);
        fail();
    } catch (RuntimeException e) {
        assertEquals(ex, e);
    }
    for (int i = 0; i < locks.length; i++) {
        if (i <= 4) {
            verify(locks[i], times(1)).lock();
            verify(locks[i], times(1)).unlock();
        } else if (i > 5) {
            verify(locks[i], times(0)).lock();
            verify(locks[i], times(0)).unlock();
        } else {
            verify(locks[i], times(1)).lock();
            verify(locks[i], times(0)).unlock();
        }
        verifyNoMoreInteractions(locks[i]);
    }
}

