    for (ObjectSubjectRatingTriplet<Integer, Integer> triplet : toList(ratings)) {
        double prediction = Math.round(mdl.predict(triplet));
        if (Math.abs(prediction - triplet.getRating()) >= 1e-5)
            incorrect++;
