 */
@Test
public void testCalculation() {
    Map<Vector, Double> linearSet = new HashMap<>();
    linearSet.put(VectorUtils.of(0.), 0.);
    linearSet.put(VectorUtils.of(1.), 1.);
    linearSet.put(VectorUtils.of(2.), 2.);
    linearSet.put(VectorUtils.of(3.), 3.);
    IgniteModel<Vector, Double> linearModel = v -> v.get(0);
    IgniteModel<Vector, Double> squareModel = v -> Math.pow(v.get(0), 2);
    EvaluationResult linearRes = Evaluator.evaluateRegression(linearSet, linearModel, Vector::labeled);
    assertEquals(0., linearRes.get(MetricName.MAE), 0.01);
    assertEquals(0., linearRes.get(MetricName.MSE), 0.01);
    assertEquals(0., linearRes.get(MetricName.R2), 0.01);
    assertEquals(0., linearRes.get(MetricName.RSS), 0.01);
    assertEquals(0., linearRes.get(MetricName.RMSE), 0.01);
    EvaluationResult squareRes = Evaluator.evaluateRegression(linearSet, squareModel, Vector::labeled);
    assertEquals(2., squareRes.get(MetricName.MAE), 0.01);
    assertEquals(10., squareRes.get(MetricName.MSE), 0.01);
    assertEquals(8., squareRes.get(MetricName.R2), 0.01);
    assertEquals(40., squareRes.get(MetricName.RSS), 0.01);
    assertEquals(Math.sqrt(10), squareRes.get(MetricName.RMSE), 0.01);
}

/**
 */
@Test
public void testMap() {
    UniformMapper<Integer, Integer> mapper = new SHA256UniformMapper<>(new Random(42));
    int cnt = 0;
    for (int i = 0; i < 100_000; i++) {
        double pnt = mapper.map(i, i);
        if (pnt < 0.2)
            cnt++;
    }
    double err = 1.0 * Math.abs(cnt - 20_000) / 20_000;
    // Hash function should provide a good distribution so that error should be less that 2% in case 10^5 tests.
    assertTrue(err < 0.02);
}

/**
 */
@Test
public void testMapAndMapAgain() {
    UniformMapper<Integer, Integer> firstMapper = new SHA256UniformMapper<>(new Random(42));
    UniformMapper<Integer, Integer> secondMapper = new SHA256UniformMapper<>(new Random(21));
    int cnt = 0;
    for (int i = 0; i < 100_000; i++) {
        double firstPnt = firstMapper.map(i, i);
        double secondPnt = secondMapper.map(i, i);
        if (firstPnt < 0.5 && secondPnt < 0.5)
            cnt++;
    }
    double err = 1.0 * Math.abs(cnt - 25_000) / 25_000;
    // Hash function should provide a good distribution so that error should be less that 2% in case 10^5 tests.
    assertTrue(err < 0.02);
}

