@Test
public void testDeadlock() throws Exception {
    try {
        Ignite g = startGrid(1);
        final CountDownLatch latch = new CountDownLatch(1);
        g.events().localListen(new IgnitePredicate<Event>() {

            @Override
            public boolean apply(Event evt) {
                assert evt.type() == EVT_NODE_JOINED;
                latch.countDown();
                return true;
            }
        }, EVT_NODE_JOINED);
        IgniteInternalFuture<?> f = multithreadedAsync(new Callable<Object>() {

            @Override
            public Object call() throws Exception {
                startGrid(2);
                return null;
            }
        }, 1);
        assert latch.await(5, SECONDS);
        info(">>> Starting task.");
        assert "2".equals(executeAsync(compute(g.cluster().forPredicate(F.equalTo(F.first(g.cluster().forRemotes().nodes())))), "GarHelloWorldTask", "HELLOWORLD.MSG").get(60000));
        f.get();
    } finally {
        stopAllGrids();
    }
}

/**
 * Starts server node with URI deployment of empty directory.
 * Starts client node.
 * In a separate thread, load entry processor from p2p class loader.
 * Try to invoke it on server node, catch expected exception.
 * Check that server node is operational after.
 *
 * @throws Exception if failed.
 */
@Test
public void test() throws Exception {
    try {
        startGrid(1);
        final Ignite ignite2 = startClientGrid(2);
        Thread thread = new Thread(() -> {
            try {
                ClassLoader cl = new GridTestExternalClassLoader(new URL[] { new URL(GridTestProperties.getProperty("p2p.uri.cls")) });
                Thread.currentThread().setContextClassLoader(cl);
                Class cls = cl.loadClass(RUN_CLS);
                EntryProcessor proc = (EntryProcessor) cls.newInstance();
                retVal = ignite2.getOrCreateCache(DEFAULT_CACHE_NAME).invoke(0, proc);
            } catch (Exception ex) {
                if (X.hasCause(ex, "Failed to find class with given class loader for unmarshalling", OptimizedMarshallerInaccessibleClassException.class)) {
                    ignite2.log().warning("Caught expected exception", ex);
                    retVal = 0;
                } else
                    throw new RuntimeException(ex);
            }
        });
        thread.start();
        thread.join();
        assertEquals(0, retVal);
        assertEquals(0, grid(1).cache(DEFAULT_CACHE_NAME).size());
    } finally {
        stopAllGrids();
        if (file != null)
            file.toFile().delete();
    }
}

