    final UUID nodeId = ignite(2).cluster().localNode().id();
    IgniteInternalFuture<?> fut = GridTestUtils.runMultiThreadedAsync(new Runnable() {

        @Override
        public void run() {
            assertTrue(spi.pingNode(nodeId));
        }
    }, 32, "ping");
